--
-- Name: fn_total_working_days(date, date); Type: FUNCTION; Schema: kaveri_analytics; Owner: tableaukaveri
--

CREATE FUNCTION kaveri_analytics.fn_total_working_days(date1 date, date2 date) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	total_working_days integer;
BEGIN
	SELECT COUNT(*) into total_working_days FROM kaveri_analytics.vw_kaveri_calendar_master
	WHERE DATE BETWEEN date1 AND date2 and status='W';
	
	return total_working_days;
END;
$$;


ALTER FUNCTION kaveri_analytics.fn_total_working_days(date1 date, date2 date) OWNER TO tableaukaveri;

