			INTO var_application_count, var_0_3_days, var_4_5_days, var_6_10_days, var_10_days_more 
			from
			(
				select sum(count) as application_count,
				   sum(case when status= '0-3 Days' then count else 0 end)as var_0_3_Day,
				   sum(case when status= '4-5 Days' then count else 0 end) as var_4_5_Day,
				   sum(case when status= '6-10 Days' then count else 0 end) as var_6_10_Day,
				   sum(case when status= '10 Days & above' then count else 0 end) as var_10_Day_more
