				(
					select count(applicationnumber) as count,
					case
						WHEN x.difference >= 0 AND x.difference <= 3 THEN '0-3 Days'
						WHEN x.difference >= 4 AND x.difference <= 5 THEN '4-5 Days'
						WHEN x.difference >= 6 AND x.difference <= 10 THEN '6-10 Days'
						WHEN x.difference >= 11 THEN '10 Days & above'
						ELSE NULL
							
