						then
							insert into kaveri_analytics.tbl_kaveri_status_wise_active(date,financial_year_id,financial_year,month_id,month_name,district_code,district_name,srocode,sroname,propertytype_id_csg,property_type,cd102,cd103,cd104,cd105,cd106,cd107,cd108,cd109,cd110,cd111,cd112,cd113,cd114,cd115,cd116,cd117,cd119,cd120,cd121,cd124,cd125,cd133,cd134,cd135,cd136)
							values(var_date,var_fin_year_id, var_fin_year,var_Month_id,var_monthname,var_district_code,var_district_name,var_srocode,var_sroname, 2, 'Non Agriculture',COALESCE(var_application_count_cursor.cd102,0),COALESCE(var_application_count_cursor.cd103,0),COALESCE(var_application_count_cursor.cd104,0),COALESCE(var_application_count_cursor.cd105,0),COALESCE(var_application_count_cursor.cd106,0),COALESCE(var_application_count_cursor.cd107,0),
							COALESCE(var_application_count_cursor.cd108,0),COALESCE(var_application_count_cursor.cd109,0),COALESCE(var_application_count_cursor.cd110,0),COALESCE(var_application_count_cursor.cd111,0),COALESCE(var_application_count_cursor.cd112,0),COALESCE(var_application_count_cursor.cd113,0),COALESCE(var_application_count_cursor.cd114,0),COALESCE(var_application_count_cursor.cd115,0),COALESCE(var_application_count_cursor.cd116,0),
							COALESCE(var_application_count_cursor.cd117,0),COALESCE(var_application_count_cursor.cd119,0),COALESCE(var_application_count_cursor.cd120,0),COALESCE(var_application_count_cursor.cd121,0),COALESCE(var_application_count_cursor.cd124,0),COALESCE(var_application_count_cursor.cd125,0),COALESCE(var_application_count_cursor.cd133,0),COALESCE(var_application_count_cursor.cd134,0),COALESCE(var_application_count_cursor.cd135,0),COALESCE(var_application_count_cursor.cd136,0));
						else
									
							update kaveri_analytics.tbl_kaveri_status_wise_active
							set date=var_date,
							cd102=COALESCE(var_application_count_cursor.cd102,0),
