							cd119=COALESCE(var_application_count_cursor.cd119,0),
							cd120=COALESCE(var_application_count_cursor.cd120,0),
							cd121=COALESCE(var_application_count_cursor.cd121,0),
							cd124=COALESCE(var_application_count_cursor.cd124,0),
							cd125=COALESCE(var_application_count_cursor.cd125,0),
							cd133=COALESCE(var_application_count_cursor.cd133,0),
							cd134=COALESCE(var_application_count_cursor.cd134,0),
							cd135=COALESCE(var_application_count_cursor.cd135,0),
							cd136=COALESCE(var_application_count_cursor.cd136,0)
							where financial_year_id=var_fin_year_id and month_id=var_Month_id 
							and srocode=var_srocode and propertytype_id_csg=2;
						end if;
					end if;
						
