						insert into kaveri_analytics.tbl_kaveri_status_wise_history
						(
							select financial_year_id,financial_year,month_id,month_name,district_code,district_name,srocode,sroname,propertytype_id_csg,property_type,cd102,cd103,cd104,cd105,cd106,cd107,cd108,cd109,cd110,cd111,cd112,cd113,cd114,cd115,cd116,cd117,cd119,cd120,cd121,cd124,cd125,cd133,cd134,cd135,cd136
							from kaveri_analytics.tbl_kaveri_status_wise_active
							where date=var_date and financial_Year_id=var_fin_year_id and month_id=var_Month_id and srocode=var_srocode and propertytype_id_csg=2
						);
							
					else
						update  kaveri_analytics.tbl_kaveri_status_wise_history
						set     cd102=a.cd102,
								cd103=a.cd103,
								cd104=a.cd104,
								cd105=a.cd105,
							    cd106=a.cd106,
