		then 
			var_application_count=0;
			var_0_to_1_Lakhs=0;
			var_1_to_5_Lakhs=0;
			var_5_to_10_Lakhs=0;
			var_10_to_20_Lakhs=0;
			var_20_to_50_Lakhs=0;
			var_50_Lakhs_to_1_Crores=0;
			var_1_to_5_Crores=0;
			var_5_Crores_Above=0;
			
			select COALESCE(total_application,0),COALESCE(var_0_to_1_Lakh,0),
			       COALESCE(var_1_to_5_Lakh,0), COALESCE(var_5_to_10_Lakh,0),
				   COALESCE(var_10_to_20_Lakh,0),COALESCE(var_20_to_50_Lakh,0),
				   COALESCE(var_50_Lakh_to_1_Crore,0), COALESCE(var_1_to_5_Crore,0),
				   COALESCE(var_5_Crore_Above,0)
			into var_application_count,var_0_to_1_Lakhs,var_1_to_5_Lakhs,
			var_5_to_10_Lakhs,var_10_to_20_Lakhs,var_20_to_50_Lakhs,
			var_50_Lakhs_to_1_Crores,var_1_to_5_Crores,var_5_Crores_Above 
			from
			(
				select 	sum(total_application) as total_application, 
				sum(case when status='0_to_1_Lakhs' then total_application else 0 end ) as var_0_to_1_Lakh,
				sum(case when status='1_to_5_Lakhs' then total_application else 0 end ) as var_1_to_5_Lakh,
