		select count(distinct t.applicationnumber) into var_other_status
		from	
		(
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD106','CD107','CD121','CD124','CD125','CD133') and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
		)t;
	
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		--Applications Pending at SRO for Registration (step 5 - step 10)
		select count(distinct t.applicationnumber) into var_pending_sro_reg
