			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD108','CD109','CD110','CD111','CD112','CD113','CD114','CD115','CD116','CD117') and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
		)t;
		
		var_id=2;
	

		
		begin
			--call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_financial_year as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_month_all as character varying(15)),cast(var_month_id_all as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
		exception
