			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_financial_year as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_month_all as character varying(15)),cast(var_month_id_all as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
		exception
			when others then
				RAISE NOTICE 'kaveri_analytics.sp_doc_reg_sla_reasons: %', SQLERRM;
		end;
		
		

		------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		--stamp duty
		select COALESCE(sum(t.amountpaid),0) into var_stamp_duty
		from
		(
			SELECT  distinct a.applicationnumber,b.amountpaid,b.feerulecode
			FROM kaveri.applicantapplicationdetails a join 
			kaveri.feesrequired b on a.applicationnumber::text = b.applicationnumber::text
			join kaveri.propertymaster c on a.applicationnumber::text = c.applicationnumber::text 
			join kaveri.documentmaster d on a.applicationnumber::text = d.applicationnumber::text
			join kaveri.registrationarticles x on  c.regarticlecode = x.regarticlecode 
			WHERE date(d.ackdatetime) between var_financial_year and var_date AND 
			a.applicationtypeid in (1, 2) 
			AND a.currentstatus::text ='CD120' AND a.bookid = 1 AND c.propertytypeid <> 1001 
			AND b.feerulecode in(36,110) AND c.propertytypeid in (17, 18)
			and a.srocode=var_rec.srocode
			group by a.applicationnumber,b.amountpaid,b.feerulecode
		)t;
		
		
		--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		--registration_fee
		
		select COALESCE(sum(t.amountpaid),0) into var_registration_fee
		from
		(
			SELECT  distinct a.applicationnumber,b.amountpaid,b.feerulecode
			FROM kaveri.applicantapplicationdetails a join 
			kaveri.feesrequired b on a.applicationnumber::text = b.applicationnumber::text
			join kaveri.propertymaster c on a.applicationnumber::text = c.applicationnumber::text 
			join kaveri.documentmaster d on a.applicationnumber::text = d.applicationnumber::text
			join kaveri.registrationarticles x on  c.regarticlecode = x.regarticlecode 
			WHERE  date(d.ackdatetime) between var_financial_year and var_date and a.applicationtypeid in (1,2) 
			AND a.currentstatus::text = 'CD120' AND a.bookid = 1 AND c.propertytypeid <> 1001 
			AND b.feerulecode in(1,65,109) AND c.propertytypeid in (17,18)
			and a.srocode=var_rec.srocode
			group by a.applicationnumber,b.amountpaid,b.feerulecode
		)t;
		
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

