		join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber 
		join kaveri.feesrequired e on a.applicationnumber = e.applicationnumber 
		where date(c.ackdatetime) between var_begin_date and var_date 
		and a.currentstatus='CD120' 
