		begin
			--call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_non_agri as int),cast(var_rec.district_name_non_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Non Agriculture');
		exception
			when others then
				RAISE NOTICE 'kaveri_analytics.sp_doc_reg_sla_reasons: %', SQLERRM;
		end;
		
		
		----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		var_id=6;
		
		begin
			--call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_non_agri as int),cast(var_rec.district_name_non_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Non Agriculture');
		exception
			when others then
				RAISE NOTICE 'kaveri_analytics.sp_doc_reg_sla_reasons: %', SQLERRM;
		end;
		

		---kaveri 1 data
		if var_fin_year_id=2 and var_month_id in (1,2,3)
		then	
			
			select count(distinct id) into var_total_applications_kaveri1 from 
			kaveri_analytics.tbl_kaveri1_doc_reg_details 
			where financial_year=var_fin_year  and stamp5datetime between var_begin_date and var_date  and srocode=var_rec.srocode and property_type='Non Agriculture';
		
			select COALESCE(sum(stampdutycollected),0),COALESCE(sum(regfeescollected),0) into var_stamp_duty_kaveri1,var_reg_fees_kaveri1
			from kaveri_analytics.tbl_kaveri1_doc_reg_details 
			where financial_year=var_fin_year and stamp5datetime between var_begin_date and var_date  and srocode=var_rec.srocode and property_type='Non Agriculture';
		
			

			var_total_applications=var_total_applications+var_reg_applications+var_total_applications_kaveri1;
			var_reg_applications=var_reg_applications+var_total_applications_kaveri1;
		
			var_stamp_duty=var_stamp_duty+var_stamp_duty_kaveri1;
			var_registration_fee=var_registration_fee+var_reg_fees_kaveri1;
		else
			
			var_total_applications=var_total_applications+var_reg_applications; 
		end if;
		
		--var_total_applications=var_total_applications+var_reg_applications; changes to uncomment after kaveri 1 data is approved
		
		
		if (var_date=var_begin_date) 
		then
			
			delete from kaveri_analytics.tbl_kaveri_kpi_details_active where srocode=var_rec.srocode and propertytype_id_csg=2 and month_id<>13;
			insert into kaveri_analytics.tbl_kaveri_kpi_details_active
			(	date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				appln_with_sro,
				appln_sro_doc_ver,
				appln_pend_citizen_pay_appt,
				appln_pend_sro_reg,
				appln_hold_citizen,
				total_doc_reg,
				appln_withdrawn,
				appln_refused_sro,
				stamp_duty,
				registration_fee
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_month_id,
				var_monthname,
				var_rec.district_code_non_agri,
				var_rec.district_name_non_agri,
				var_rec.srocode,
				var_rec.sroname,
				2,
				'Non Agriculture',
				COALESCE(var_total_applications,0),
				COALESCE(var_total_appln_sro_doc_ver,0),
				COALESCE(var_other_status,0),
				COALESCE(var_pending_sro_reg,0),
				COALESCE(var_onhold,0),
				COALESCE(var_reg_applications,0),
				COALESCE(var_app_withdrawn,0),
				COALESCE(var_app_refused_sro,0),
				COALESCE(var_stamp_duty,0),
				COALESCE(var_registration_fee,0)
			);
		else
			
			insert into kaveri_analytics.tbl_kaveri_kpi_details_active
			(	date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				appln_with_sro,
				appln_sro_doc_ver,
				appln_pend_citizen_pay_appt,
				appln_pend_sro_reg,
				appln_hold_citizen,
				total_doc_reg,
				appln_withdrawn,
				appln_refused_sro,
				stamp_duty,
				registration_fee
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_month_id,
				var_monthname,
				var_rec.district_code_non_agri,
				var_rec.district_name_non_agri,
				var_rec.srocode,
				var_rec.sroname,
				2,
				'Non Agriculture',
				COALESCE(var_total_applications,0),
				COALESCE(var_total_appln_sro_doc_ver,0),
				COALESCE(var_other_status,0),
				COALESCE(var_pending_sro_reg,0),
				COALESCE(var_onhold,0),
				COALESCE(var_reg_applications,0),
				COALESCE(var_app_withdrawn,0),
				COALESCE(var_app_refused_sro,0),
				COALESCE(var_stamp_duty,0),
				COALESCE(var_registration_fee,0)
			);
			
		end if;
		select count(*) into var_count from kaveri_analytics.tbl_kaveri_kpi_details_history where financial_year_id=var_fin_year_id and  month_id=var_month_id and srocode=var_rec.srocode and propertytype_id_csg=2;
		if (var_date=var_begin_date) or (var_count=0)
		then
			BEGIN
				
				insert into kaveri_analytics.tbl_kaveri_kpi_details_history
				(
					select 
					financial_year_id,
					financial_year,
					month_id,
					month_name,
					district_code,
					district_name,
					srocode,
					sroname,
					propertytype_id_csg,
					property_type,
					appln_with_sro,
					appln_sro_doc_ver,
					appln_pend_citizen_pay_appt,
					appln_pend_sro_reg,
					appln_hold_citizen,
					total_doc_reg,
					appln_withdrawn,
					appln_refused_sro,
					stamp_duty,
					registration_fee
					from kaveri_analytics.tbl_kaveri_kpi_details_active a
					where a.date=var_date and
					a.financial_year_id=var_fin_year_id and  a.month_id=var_month_id 
					and a.srocode=var_rec.srocode and a.propertytype_id_csg=2
				);
				
			EXCEPTION
				-- Handle exception
				WHEN others THEN
				RAISE NOTICE 'Error occurred: %', SQLERRM;
				ROLLBACK;
			END;
		else
			
			BEGIN
				UPDATE kaveri_analytics.tbl_kaveri_kpi_details_history
				SET appln_with_sro=a.appln_with_sro,
					appln_sro_doc_ver=a.appln_sro_doc_ver,
					appln_pend_citizen_pay_appt=a.appln_pend_citizen_pay_appt,
					appln_pend_sro_reg=a.appln_pend_sro_reg,
					appln_hold_citizen=a.appln_hold_citizen,
					total_doc_reg=a.total_doc_reg,
					appln_withdrawn=a.appln_withdrawn,
					appln_refused_sro=a.appln_refused_sro,
					stamp_duty=a.stamp_duty,
					registration_fee=a.registration_fee
				FROM (	select appln_with_sro,
							   appln_sro_doc_ver,
							   appln_pend_citizen_pay_appt,
							   appln_pend_sro_reg,
							   appln_hold_citizen,
							   total_doc_reg,
							   appln_withdrawn,
							   appln_refused_sro,
							   stamp_duty,
							   registration_fee
							   from kaveri_analytics.tbl_kaveri_kpi_details_active b
							   where b.date=var_date and b.financial_year_id=var_fin_year_id and   b.month_id=var_month_id 
							   and b.srocode=var_rec.srocode and b.propertytype_id_csg=2) as a
				where financial_year_id=var_fin_year_id and  month_id=var_month_id and srocode=var_rec.srocode and propertytype_id_csg=2;
			EXCEPTION
				-- Handle exception
				WHEN others THEN
				RAISE NOTICE 'Error occurred: %', SQLERRM;
				ROLLBACK;
			END;
			
		end if;
		
		----Bucket wise revenue
		
		begin
			var_id=7;
			--call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_non_agri as int),cast(var_rec.district_name_non_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Non Agriculture');
		exception
			when others then
				RAISE NOTICE 'kaveri_analytics.sp_doc_reg_sla_reasons: %', SQLERRM;
		end;
	

	

		
	END LOOP;
	CLOSE sro_cursor;
	Raise notice 'SP Completes';
	exception
		when others then
			get stacked diagnostics
				var_error_msg=MESSAGE_TEXT;
END;
$$;


ALTER PROCEDURE kaveri_analytics.sp_kaveri_doc_registration_1(IN date date) OWNER TO tableaukaveri;

--
-- Name: sp_kaveri_doc_registration_2(date); Type: PROCEDURE; Schema: kaveri_analytics; Owner: tableaukaveri
--

CREATE PROCEDURE kaveri_analytics.sp_kaveri_doc_registration_2(IN date date)
    LANGUAGE plpgsql
    AS $$
DECLARE 
	--varaible declarations
	var_rec record;
	var_error_msg text;
	var_date date;
	var_fin_year    character varying(15);
	var_monthname   character varying(15);
	var_day int;
	var_month int;
	var_fin_year_id int;
	var_month_id int;
	var_total_applications bigint;
	var_begin_date date;
	var_total_appln_sro_doc_ver bigint;
	var_other_status bigint;
	var_reg_applications bigint;
	var_pending_sro_reg bigint;
	var_onhold bigint;
	var_app_withdrawn bigint; 
	var_app_refused_sro bigint;
	var_stamp_duty numeric;
	var_registration_fee numeric;
	var_financial_year date;
	var_month_all  character varying(15);
	var_month_id_all int;
	var_total_applications_kaveri1 bigint;
	var_property_type character varying(15);
	var_id int;
	var_count int;
	var_stamp_duty_kaveri1 numeric;
	var_reg_fees_kaveri1 numeric;
	var_year int;

	--Cursor which calls all the sro in a loop
	sro_cursor CURSOR 
	FOR 
	select * from kaveri_analytics.tbl_district_sro_mapping order by srocode;
	
BEGIN
	Raise notice 'SP Starts';
	var_date=date;--system date
	
	SELECT
    CASE
        WHEN EXTRACT(MONTH FROM cast(var_date as date)) >= 4 THEN DATE_TRUNC('YEAR', cast(var_date as date)) + INTERVAL '3 months'
        ELSE DATE_TRUNC('YEAR', cast(var_date as date)) - INTERVAL '9 months'
    END into var_financial_year;

	var_financial_year=date(var_financial_year);

	--Financial_year  extraction 
	var_month=EXTRACT(month FROM var_date);--month extraction from the current month 
	
	if var_month in (1,2,3)
	then
		var_fin_year=concat(EXTRACT(year FROM var_date) - 1::numeric, '-', "substring"(EXTRACT(year FROM var_date)::character varying::text, 3, 2));--financial year id extraction 
	else
		var_fin_year=concat(EXTRACT(year FROM var_date), '-', "substring"(EXTRACT(year FROM var_date)::character varying::text, 3, 2)::integer + 1);
	end if;
	
	--monthname extraction
	var_monthname=TRIM(TRAILING FROM to_char(var_date, 'Month'::text));

	--day extraction
	var_day=EXTRACT(day FROM var_date);

	--Financial Year ID and Month ID extraction
	
	
	select Month_id into var_month_id from kaveri_analytics.tbl_month_master where Month_Name=var_monthname; 
	
	
	select financial_year_id into var_fin_year_id from kaveri_analytics.tbl_financial_year_master where financial_year=var_fin_year;
	
	
	--begin date of the month
	var_begin_date=var_date-(var_day-1);--gives begining date of the month 
	

	
	var_month_all='ALL';--finanicial year begin to till date
	
	
	var_month_id_all=13;

	
	OPEN sro_cursor;
	LOOP
		FETCH  sro_cursor INTO var_rec;
    EXIT WHEN NOT FOUND;
		
		--declarations to zero
		
		var_total_applications=0;
		var_total_appln_sro_doc_ver=0;
		var_reg_applications=0;
		var_other_status=0;
		var_pending_sro_reg=0;
		var_onhold=0;
		var_app_withdrawn=0;
		var_app_refused_sro=0;
		var_stamp_duty=0;
		var_count=0;
		var_total_applications_kaveri1=0;
		var_stamp_duty_kaveri1=0;
		var_reg_fees_kaveri1=0;
		
		raise notice 'srocode : %',var_rec.srocode;
		-----------------------------------------------------------------------Agriculture-all---------------------------------------------------------------------------------------------------------
		
	
		raise notice 'agriculture-all';
				
		var_total_applications=0;
		var_total_appln_sro_doc_ver=0;
		var_reg_applications=0;
		var_other_status=0;
		var_pending_sro_reg=0;
		var_onhold=0;
		var_app_withdrawn=0;
		var_app_refused_sro=0;
		var_stamp_duty=0;
		var_count=0;
		var_total_applications_kaveri1=0;
		var_stamp_duty_kaveri1=0;
		var_reg_fees_kaveri1=0;

		--Applications with SRO
		select count(t.applicationnumber)into var_total_applications
		from
		(	select a.applicationnumber,min(d.crtdt) 
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber 
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber 
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD102','CD103','CD104','CD105','CD106','CD107','CD108','CD109','CD110','CD111','CD112','CD113',
			'CD114','CD115','CD116','CD117','CD121','CD124','CD125','CD133','CD135','CD136')
			and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date  
			
			UNION
			
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			join kaveri.minutebook_data e on a.applicationnumber = e.applicationnumber
			join kaveri_analytics.tbl_kaveri_reason_master f on e.reasonid = f.reason_id
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus ='CD119' and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
			
			UNION
			
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			--join kaveri.minutebook_data e on a.applicationnumber = e.applicationnumber
			join kaveri_analytics.tbl_kaveri_reason_master e on a.remarks= e.reasons_desc
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus='CD134' and a.applicationtypeid in (1,2) 
			and a.bookid=2 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
			
			
		)t;

		

		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		--Applications with SROs  for Document Verification (step 1-3)
		select count(t.applicationnumber) into var_total_appln_sro_doc_ver 
		from
		(
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD102','CD103','CD104','CD105') and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date  
			
		)t;
		
	
		var_id=1;
		var_property_type='Agriculture';
		
		begin
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_financial_year as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_month_all as character varying(15)),cast(var_month_id_all as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
		exception
			when others then
				RAISE NOTICE 'kaveri_analytics.sp_doc_reg_sla_reasons: %', SQLERRM;
		end;
		
		
		---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		
		--applications Pending with citizen for Payment & Appt. booking(step-4)
		select count(distinct t.applicationnumber) into var_other_status
		from	
		(
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD106','CD107','CD121','CD124','CD125','CD133') and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
		)t;
	
		
		-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
		--Applications Pending at SRO for Registration (step 5 - step 10)
		select count(distinct t.applicationnumber) into var_pending_sro_reg
		from	
		(
			select a.applicationnumber,min(d.crtdt)
			from kaveri.applicantapplicationdetails a
			join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber
			join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
			join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber
			where --date(d.crtdt) between var_financial_year and var_date and 
			a.currentstatus in ('CD108','CD109','CD110','CD111','CD112','CD113','CD114','CD115','CD116','CD117') and a.applicationtypeid in (1,2) 
			and a.bookid=1 and b.propertytypeid<>1001 and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
			and a.srocode=var_rec.srocode and a.isduecorrection='False'
			group by a.applicationnumber
			having min(date(d.crtdt)) between var_financial_year and var_date 
		)t;
		
		var_id=2;
	

		
		begin
			--call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_begin_date as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_monthname as character varying(15)),cast(var_month_id as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_financial_year as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_month_all as character varying(15)),cast(var_month_id_all as int),cast(var_rec.district_code_agri as int),cast(var_rec.district_name_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Agriculture');
		exception
