		--applications registered 
		select count( distinct a.applicationnumber) into var_reg_applications
		from kaveri.applicantapplicationdetails a
		join kaveri.propertymaster b on a.applicationnumber=b.applicationnumber 
		join kaveri.documentmaster c on a.applicationnumber=c.applicationnumber
		join kaveri.applicationaudit d on a.applicationnumber=d.applicationnumber 
		join kaveri.feesrequired e on a.applicationnumber = e.applicationnumber 
		where date(c.ackdatetime) between var_financial_year and var_date 
		and a.currentstatus='CD120'
		AND e.feerulecode in(1,36,65,109,110) 
		and a.applicationtypeid in (1,2) and a.bookid=1 and b.propertytypeid<>1001 
		and b.propertytypeid in (17,18) and a.currentstatus=d.wrkflowstatusid
		and a.srocode=var_rec.srocode;
		
		
