		select count(*) into var_count from kaveri_analytics.tbl_kaveri_kpi_details_history where financial_year_id=var_fin_year_id and  month_id=var_month_id_all and srocode=var_rec.srocode and propertytype_id_csg=1;
		if (var_date=var_financial_year) or (var_count=0)
