			call kaveri_analytics.sp_doc_reg_sla_reasons(var_id,cast(var_financial_year as date),cast(var_date as date),cast(var_fin_year as character varying(15)),cast(var_fin_year_id as int),cast(var_month_all as character varying(15)),cast(var_month_id_all as int),cast(var_rec.district_code_non_agri as int),cast(var_rec.district_name_non_agri as character varying(15)),cast(var_rec.srocode as int),cast(var_rec.sroname as character varying(15)),'Non Agriculture');
