								group by t.applicationnumber,t.ce110_date,t.kaverisrocode
							
							)b
						)c
					)d
				)e
			)f;
				
		end if;	
	END LOOP;
	CLOSE sro_cursor;
	exception
		when others then
			get stacked diagnostics
				var_error_msg=MESSAGE_TEXT; 
END;
$$;


ALTER PROCEDURE kaveri_analytics.sp_kaveri_ec_application_entry(IN date date) OWNER TO postgres;

--
-- Name: sp_kaveri_ec_avg_calculation(date); Type: PROCEDURE; Schema: kaveri_analytics; Owner: tableaukaveri
--

CREATE PROCEDURE kaveri_analytics.sp_kaveri_ec_avg_calculation(IN date date)
    LANGUAGE plpgsql
    AS $$
DECLARE

	var_rec record;
	var_error_msg text;
	var_date date;
	var_fin_year    character varying(15);
	var_monthname   character varying(15);
	var_day int;
	var_month int;
	var_fin_year_id int;
	var_month_id int;
	var_total_applications bigint;
	var_begin_date date;
	var_financial_year date;
	var_month_all  character varying(15);
	var_month_id_all int;
	var_total_applications_kaveri1 bigint;
	var_property_type character varying(15);
	var_id int;
	var_count int;
	var_year int;
	var_tt_allocate_appln numeric;
	var_tt_prepare_ec numeric;
	var_tt_verify_ec numeric;
	var_tt_approve_ec numeric;
	var_tt_deliver numeric;
	var_sro_list character varying(1000);
	var_application_cursor record;
	sro_cursor CURSOR 
	FOR 
	select * from kaveri_analytics.tbl_district_sro_mapping order by srocode;
	
BEGIN
	var_date=date;--system date

	SELECT
    CASE
        WHEN EXTRACT(MONTH FROM cast(var_date as date)) >= 4 THEN DATE_TRUNC('YEAR', cast(var_date as date)) + INTERVAL '3 months'
        ELSE DATE_TRUNC('YEAR', cast(var_date as date)) - INTERVAL '9 months'
    END into var_financial_year;

	var_financial_year=date(var_financial_year);

	--Financial_year  extraction 
	var_month=EXTRACT(month FROM var_date);--month extraction from the current month 
	
	if var_month in (1,2,3)
	then
		var_fin_year=concat(EXTRACT(year FROM var_date) - 1::numeric, '-', "substring"(EXTRACT(year FROM var_date)::character varying::text, 3, 2));--financial year id extraction 
	else
		var_fin_year=concat(EXTRACT(year FROM var_date), '-', "substring"(EXTRACT(year FROM var_date)::character varying::text, 3, 2)::integer + 1);
	end if;
	
	raise notice'Fin year %',var_fin_year;

	--monthname extraction
	var_monthname=TRIM(TRAILING FROM to_char(var_date, 'Month'::text));

	raise notice'MONTHNAME %',var_monthname;
	
	--day extraction
	var_day=EXTRACT(day FROM var_date);
	
	raise notice'DAY %',var_day;

	--Financial Year ID and Month ID extraction
	select Month_id into var_month_id from kaveri_analytics.tbl_month_master where Month_Name=var_monthname; 
	select financial_year_id into var_fin_year_id from kaveri_analytics.tbl_financial_year_master where financial_year=var_fin_year;

	
	--begin date of the month
	var_begin_date=var_date-(var_day-1);--gives begining date of the month 
	var_month_all='ALL';--finanicial year begin to till date
	var_month_id_all=13;

	--Kaveri_1_changes starts
	raise notice 'var_sro_list%',var_sro_list;
	SELECT STRING_AGG(srocode::text, ',' ORDER BY srocode) into var_sro_list
	FROM 
	(
		SELECT DISTINCT srocode
		FROM kaveri.departmentusers
		WHERE designationid IN (2,3)
	)t;
		
	--Kaveri_1_changes ends
	
	raise notice 'var_sro_list%',var_sro_list;
	raise notice'calling sro cursor';
	
	OPEN sro_cursor;
	LOOP
		FETCH  sro_cursor INTO var_rec;
    EXIT WHEN NOT FOUND;
	
		var_tt_deliver=0;
		var_tt_allocate_appln=0;
		var_tt_prepare_ec=0;
		var_tt_verify_ec=0;
		var_tt_approve_ec=0;
		
		raise notice 'srocode ----------------------:%',var_rec.srocode;
		------------------------------------------------------------------------------------Agriculture------------------------------------------------------------------------------------------------------------------------
		------------------------------------------------------------------------------------before 2004------------------------------------------------------------------------------------------------------------------------
		--------------------------------------------------------------------------------Time taken to Deliver (A1)---------------------------------------------------------------------------------------------------------------------------------------------------------------------
		raise notice 'agriculture -before 2004-Time taken to Deliver:%',var_tt_deliver;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_deliver
		FROM 	
		(	
			--SELECT  e.ec_id,e.ce104_date,e.ce110_date,e.total_working_days,e.working_days_8_hr,e.ce104_status_time,e.ce110_status_time,--Kaveri_1_changes 
			SELECT  e.applicationnumber,e.ce104_date,e.ce102_date,e.total_working_days,e.working_days_8_hr,e.ce104_status_time,e.ce102_status_time,--Kaveri_1_changes 
			CASE
				WHEN e.working_days_8_hr = 0 THEN 0
				WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce102_date::date THEN 0
			ELSE e.working_days_8_hr * 28800
			END AS actual_working_hours,
			CASE
				WHEN e.working_days_8_hr = 0 AND e.ce104_date::date <> e.ce102_date::date THEN e.ce104_status_time + e.ce102_status_time
				WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce102_date::time without time zone - e.ce104_date::time without time zone), '-2'::integer)
				WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce102_date::date THEN e.ce104_status_time + e.ce102_status_time
			ELSE (e.working_days_8_hr * 28800)::numeric + e.ce104_status_time + e.ce102_status_time
			END AS total_working_hrs
			from
			(
				--SELECT d.ec_id,d.ce104_date,d.ce110_date,d.total_working_days,d.working_days_8_hr,--Kaveri_1_changes 
				SELECT d.applicationnumber,d.ce104_date,d.ce102_date,d.total_working_days,d.working_days_8_hr,--Kaveri_1_changes 
				CASE
					WHEN "substring"(d.ce104_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce104_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce104_status_time
				END AS ce104_status_time,
				CASE
					WHEN "substring"(d.ce102_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce102_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce102_status_time
				END AS ce102_status_time	
				FROM
				(
					--SELECT c.ec_id,c.ce104_date,c.ce110_date,c.total_working_days,c.ce104_status_time,c.ce110_status_time,--Kaveri_1_changes 
					SELECT c.applicationnumber,c.ce104_date,c.ce102_date,c.total_working_days,c.ce104_status_time,c.ce102_status_time,--Kaveri_1_changes 
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce104_date::date <> c.ce102_date::date THEN 1
						ELSE 0
					END AS working_days_8_hr
					FROM 
					( 	
						--SELECT b.ec_id,b.ce104_date,b.ce110_date,--Kaveri_1_changes 
						SELECT b.applicationnumber,b.ce104_date,b.ce102_date,--Kaveri_1_changes 
						kaveri_analytics.fn_total_working_days(b.ce104_date::date, b.ce102_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce104_date::time without time zone), '-2'::integer) AS ce104_status_time,
						round(EXTRACT(epoch FROM b.ce102_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce102_status_time
						FROM 
						(
							--Kaveri_1_changes starts
							/*select t.ec_id,ce110_date,d.submitteddatetime as ce104_date,t.kaverisrocode
							from
							(	select distinct a.ecid  as ec_id,a.signeddatetime as ce110_date,a.kaverisrocode from
								kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								where b.currentstatus='CE110'
								and date(a.signeddatetime)=var_date
								and a.propertytypeid in (17,18) and  a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode 
							)t
							join kaveri.ec_applicationdetails d on t.ec_id=d.ecid*/
							
							
							select t.applicationnumber,t.ce102_date,max(d.crtdt) as ce104_date,t.kaverisrocode
							from
							(	
								select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce102_date,a.kaverisrocode  from
								kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE102'
								where b.currentstatus in ('CE102','CE110') 
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode 
								group by a.applicationnumber,a.kaverisrocode 
								having max(date(c.crtdt)) =var_date
									
							)t
							join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE104' and t.kaverisrocode=d.srocode
							group by t.applicationnumber,t.ce102_date,t.kaverisrocode
							
							--Kaveri_1_changes ends
						)b
					)c
				)d
			)e
		)f;
		
		raise notice 'agriculture -before 2004-Time taken to Deliver:%',var_tt_deliver;
		------------------------------Time taken to Prepare the EC (Step 2)----------------------------------------------------------------------------------------------------------
		raise notice 'agriculture -before 2004-var_tt_prepare_ec:%',var_tt_prepare_ec;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_prepare_ec
		FROM 	
		(	
			--SELECT  e.ec_id,e.ce105_date,e.ce106_date,e.total_working_days,e.working_days_8_hr,e.ce105_status_time,e.ce106_status_time,
			SELECT  e.applicationnumber,e.ce104_date,e.ce112_date,e.total_working_days,e.working_days_8_hr,e.ce104_status_time,e.ce112_status_time,
					CASE
						WHEN e.working_days_8_hr = 0 THEN 0
						WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce112_date::date THEN 0
						ELSE e.working_days_8_hr * 28800
					END AS actual_working_hours,
					CASE
						WHEN e.working_days_8_hr = 0 AND e.ce104_date::date <> e.ce112_date::date THEN e.ce104_status_time + e.ce112_status_time
						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce112_date::time without time zone - e.ce104_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce112_date::date THEN e.ce104_status_time + e.ce112_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce104_status_time + e.ce112_status_time
					END AS total_working_hrs
			from
			(
				--SELECT d.ec_id,d.ce105_date,d.ce106_date,d.total_working_days,d.working_days_8_hr,
				SELECT d.applicationnumber,d.ce104_date,d.ce112_date,d.total_working_days,d.working_days_8_hr,
				CASE
					WHEN "substring"(d.ce104_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce104_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce104_status_time
				END AS ce104_status_time,
				CASE
					WHEN "substring"(d.ce112_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce112_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce112_status_time
				END AS ce112_status_time	
				FROM
				(
					--SELECT c.ec_id,c.ce105_date,c.ce106_date,c.total_working_days,c.ce105_status_time,c.ce106_status_time,
					SELECT c.applicationnumber,c.ce104_date,c.ce112_date,c.total_working_days,c.ce104_status_time,c.ce112_status_time,
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce104_date::date <> c.ce112_date::date THEN 1
						ELSE 0
					END AS working_days_8_hr
					FROM 
					( 	
						--SELECT b.ec_id,b.ce105_date,b.ce106_date,
						SELECT b.applicationnumber,b.ce104_date,b.ce112_date,
						kaveri_analytics.fn_total_working_days(b.ce104_date::date, b.ce112_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce104_date::time without time zone), '-2'::integer) AS ce104_status_time,
						round(EXTRACT(epoch FROM b.ce112_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce112_status_time
						FROM 
						(	
							--Kaveri_1_changes starts
							
							/*select t.ec_id,t.ce106_date,d.acceptedon as ce105_date,t.kaverisrocode
							from
							(	select distinct a.ecid  as ec_id,a.prepareddatetime  as ce106_date,a.kaverisrocode 
								from kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								where b.currentstatus='CE106'
								and date(a.prepareddatetime) =var_date
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode
							)t
							join kaveri.ec_applicationdetails d on t.ec_id=d.ecid*/
							
							select t.applicationnumber,max(d.crtdt) as ce104_date,t.ce112_date,t.kaverisrocode
							from
							(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce112_date,a.kaverisrocode 
								from kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE112'
								where b.currentstatus in ('CE112','CE113','CE102','CE110')
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode
								group by a.applicationnumber,a.kaverisrocode 
								having max(date(c.crtdt)) = var_date
							)t
							join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE104' and t.kaverisrocode=d.srocode
							group by t.applicationnumber,t.ce112_date,t.kaverisrocode
							
							--Kaveri_1_changes ends
						)b
					)c
				)d
			)e
		)f;
		
		raise notice 'agriculture -before 2004-var_tt_prepare_ec:%',var_tt_prepare_ec;
		-----------------------------------------Time Taken to scan and upload (Step 3)-------------------------------------------------------
		--Kaveri_1_changes starts
		raise notice 'agriculture -before 2004-Time Taken to scan and upload:%',var_tt_verify_ec;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_verify_ec
		FROM 	
		(	
			SELECT  e.applicationnumber,e.ce112_date,e.ce113_date,e.total_working_days,e.working_days_8_hr,e.ce112_status_time,e.ce113_status_time,
					CASE
						WHEN e.working_days_8_hr = 0 THEN 0
						WHEN e.working_days_8_hr = 1 AND (e.ce112_date::date + 1) = e.ce113_date::date THEN 0
						ELSE e.working_days_8_hr * 28800
					END AS actual_working_hours,
					CASE
						WHEN e.working_days_8_hr = 0 AND e.ce112_date::date <> e.ce113_date::date THEN e.ce112_status_time + e.ce113_status_time
						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce113_date::time without time zone - e.ce112_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce112_date::date + 1) = e.ce113_date::date THEN e.ce112_status_time + e.ce113_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce112_status_time + e.ce113_status_time
					END AS total_working_hrs
			from
			(
				SELECT d.applicationnumber,d.ce112_date,d.ce113_date,d.total_working_days,d.working_days_8_hr,
				CASE
					WHEN "substring"(d.ce112_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce112_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce112_status_time
				END AS ce112_status_time,
				CASE
					WHEN "substring"(d.ce113_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce113_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce113_status_time
				END AS ce113_status_time	
				FROM
				(
					SELECT c.applicationnumber,c.ce112_date,c.ce113_date,c.total_working_days,c.ce112_status_time,c.ce113_status_time,
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce112_date::date <> c.ce113_date::date THEN 1
						ELSE 0
					END AS working_days_8_hr
					FROM 
					( 	
						SELECT b.applicationnumber,b.ce112_date,b.ce113_date,
						kaveri_analytics.fn_total_working_days(b.ce112_date::date, b.ce113_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce112_date::time without time zone), '-2'::integer) AS ce112_status_time,
						round(EXTRACT(epoch FROM b.ce113_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce113_status_time
						FROM 
						(
							select t.applicationnumber,max(d.crtdt) as ce112_date,t.ce113_date,t.kaverisrocode
							from
							(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce113_date,a.kaverisrocode 
								from kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE113'
								where b.currentstatus in ('CE113','CE102','CE110')
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode
								group by a.applicationnumber,a.kaverisrocode 
								having max(date(c.crtdt)) = var_date
							)t
							join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE112' and t.kaverisrocode=d.srocode
							group by t.applicationnumber,t.ce113_date,t.kaverisrocode
						)b
					)c
				)d
			)e
		)f;
		raise notice 'agriculture -before 2004-Time Taken to scan and upload:%',var_tt_verify_ec;
		--Kaveri_1_changes ends
		--------------------------------------Time taken to digital sign (Step 4)-----------------------------------------------------------
		raise notice 'agriculture -before 2004-Time taken to digital sign:%',var_tt_approve_ec;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_approve_ec
		FROM 	
		(	
			--SELECT  e.ec_id,e.ce107_date,e.ce110_date,e.total_working_days,e.working_days_8_hr,e.ce107_status_time,e.ce110_status_time,
			SELECT  e.applicationnumber,e.ce113_date,e.ce102_date,e.total_working_days,e.working_days_8_hr,e.ce113_status_time,e.ce102_status_time,
					CASE
						WHEN e.working_days_8_hr = 0 THEN 0
						WHEN e.working_days_8_hr = 1 AND (e.ce113_date::date + 1) = e.ce102_date::date THEN 0
						ELSE e.working_days_8_hr * 28800
					END AS actual_working_hours,
					CASE
						WHEN e.working_days_8_hr = 0 AND e.ce113_date::date <> e.ce102_date::date THEN e.ce113_status_time + e.ce102_status_time
						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce102_date::time without time zone - e.ce113_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce113_date::date + 1) = e.ce102_date::date THEN e.ce113_status_time + e.ce102_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce113_status_time + e.ce102_status_time
					END AS total_working_hrs
			from
			(
				--SELECT d.ec_id,d.ce107_date,d.ce110_date,d.total_working_days,d.working_days_8_hr,
				SELECT d.applicationnumber,d.ce113_date,d.ce102_date,d.total_working_days,d.working_days_8_hr,
				CASE
					WHEN "substring"(d.ce113_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce113_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce113_status_time
				END AS ce113_status_time,
				CASE
					WHEN "substring"(d.ce102_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce102_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce102_status_time
				END AS ce102_status_time	
				FROM
				(
					--SELECT c.ec_id,c.ce107_date,c.ce110_date,c.total_working_days,c.ce107_status_time,c.ce110_status_time
					SELECT c.applicationnumber,c.ce113_date,c.ce102_date,c.total_working_days,c.ce113_status_time,c.ce102_status_time,
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce113_date::date <> c.ce102_date::date THEN 1
						ELSE 0
					END AS working_days_8_hr
					FROM 
					( 	
						--SELECT b.ec_id,b.ce107_date,b.ce110_date,
						SELECT b.applicationnumber,b.ce113_date,b.ce102_date,
						kaveri_analytics.fn_total_working_days(b.ce113_date::date, b.ce102_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce113_date::time without time zone), '-2'::integer) AS ce113_status_time,
						round(EXTRACT(epoch FROM b.ce102_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce102_status_time
						FROM 
						(
							/*select t.ec_id,t.ce110_date,d.compareddatetime as ce107_date,t.kaverisrocode
							from
							(	select distinct a.ecid  as ec_id,a.signeddatetime  as ce110_date,a.kaverisrocode 
								from  kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								where b.currentstatus='CE110'
								and date(a.signeddatetime)=var_date
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode
							)t
							join kaveri.ec_applicationdetails d on t.ec_id=d.ecid*/
							
							select t.applicationnumber,t.ce102_date,max(d.crtdt) as ce113_date,t.kaverisrocode
							from
							(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce102_date,a.kaverisrocode 
								from kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
								join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE102'
								where b.currentstatus in ('CE102','CE110')
								and a.propertytypeid in (17,18) and a.isbefore2004='True'
								and a.kaverisrocode=var_rec.srocode
								group by a.applicationnumber,a.kaverisrocode 
								having max(date(c.crtdt)) = var_date
							)t
							join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE113'
							group by t.applicationnumber,t.ce102_date,t.kaverisrocode
						)b
					)c
				)d
			)e
		)f;
		raise notice 'agriculture -before 2004-Time taken to digital sign:%',var_tt_approve_ec;
		
		if var_date=var_begin_date
		then
			raise notice 'begining of thr month so deleting previous month records';
			delete from kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active where financial_year_id=var_fin_year_id and srocode=var_rec.srocode and month_id=var_Month_id and propertytype_id_csg=1 and flag_before_2004=1;
			insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active
			(
				date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				flag_before_2004,
				time_taken_deliver,
				time_taken_allocate,
				time_taken_prepare_ec,
				time_taken_verify_ec,
				time_taken_approve_ec
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_Month_id,
				var_monthname,
				var_rec.district_code_agri,
				var_rec.district_name_agri,
				var_rec.srocode,
				var_rec.sroname,
				1,
				'Agriculture',
				1,
				COALESCE(var_tt_deliver,0),
				COALESCE(var_tt_allocate_appln,0),
				COALESCE(var_tt_prepare_ec,0),
				COALESCE(var_tt_verify_ec,0),
				COALESCE(var_tt_approve_ec,0)
			);
			
		else
			insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active
			(
				date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				flag_before_2004,
				time_taken_deliver,
				time_taken_allocate,
				time_taken_prepare_ec,
				time_taken_verify_ec,
				time_taken_approve_ec
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_Month_id,
				var_monthname,
				var_rec.district_code_agri,
				var_rec.district_name_agri,
				var_rec.srocode,
				var_rec.sroname,
				1,
				'Agriculture',
				1,
				COALESCE(var_tt_deliver,0),
				COALESCE(var_tt_allocate_appln,0),
				COALESCE(var_tt_prepare_ec,0),
				COALESCE(var_tt_verify_ec,0),
				COALESCE(var_tt_approve_ec,0)
				);
		end if;
		if var_date=var_begin_date
		then
			RAISE NOTICE 'INSIDE UPDATE';
			BEGIN
				insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_history
				(
					financial_year_id,
					financial_year,
					month_id,
					month_name,
					district_code,
					district_name,
					srocode,
					sroname,
					propertytype_id_csg,
					property_type,
					flag_before_2004,
					time_taken_deliver,
					time_taken_allocate,
					time_taken_prepare_ec,
					time_taken_verify_ec,
					time_taken_approve_ec
				) 
				values
				(
					
					var_fin_year_id,
					var_fin_year,
					var_Month_id,
					var_monthname,
					var_rec.district_code_agri,
					var_rec.district_name_agri,
					var_rec.srocode,
					var_rec.sroname,
					1,
					'Agriculture',
					1,
					COALESCE(var_tt_deliver,0),
					COALESCE(var_tt_allocate_appln,0),
					COALESCE(var_tt_prepare_ec,0),
					COALESCE(var_tt_verify_ec,0),
					COALESCE(var_tt_approve_ec,0)
				);
				RAISE NOTICE 'AFTER INSERT-BEGIN';
			EXCEPTION
			WHEN others THEN
				RAISE NOTICE 'Error occurred: %', SQLERRM;
				ROLLBACK;
			END;
		else
			RAISE NOTICE 'INSIDE UPDATE';
			begin
				update kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_history as b
				set time_taken_deliver=(b.time_taken_deliver+a.time_taken_deliver)/2,
					time_taken_allocate=(b.time_taken_allocate+a.time_taken_allocate)/2,
					time_taken_prepare_ec=(b.time_taken_prepare_ec+a.time_taken_prepare_ec)/2,
					time_taken_verify_ec=(b.time_taken_verify_ec+a.time_taken_verify_ec)/2,
					time_taken_approve_ec=(b.time_taken_approve_ec+a.time_taken_approve_ec)/2
				from (
