		end if;
		raise notice 'ALL agriculture -after 2004-Time taken to digital sign :%',var_tt_deliver;
		------------------------------Time taken to Prepare the EC (Step 2)----------------------------------------------------------------------------------------------------------
		raise notice 'ALL agriculture -after 2004-Time taken to Prepare the EC  :%',var_tt_prepare_ec;
		--if var_rec.srocode in var_sro_list
		IF position(var_rec.srocode::VARCHAR IN var_sro_list) > 0 
		then
			raise notice 'sro starts with CE105';
			SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_prepare_ec
			FROM 	
			(	
				--SELECT  e.ec_id,e.ce104_date,e.ce110_date,e.total_working_days,e.working_days_8_hr,e.ce104_status_time,e.ce110_status_time,--Kaveri_1_changes 
				SELECT  e.applicationnumber,e.ce105_date,e.ce139_date,e.total_working_days,e.working_days_8_hr,e.ce105_status_time,e.ce139_status_time,--Kaveri_1_changes 
						CASE
							WHEN e.working_days_8_hr = 0 THEN 0
							WHEN e.working_days_8_hr = 1 AND (e.ce105_date::date + 1) = e.ce139_date::date THEN 0
							ELSE e.working_days_8_hr * 28800
						END AS actual_working_hours,
						CASE
							WHEN e.working_days_8_hr = 0 AND e.ce105_date::date <> e.ce139_date::date THEN e.ce105_status_time + e.ce139_status_time
							WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce139_date::time without time zone - e.ce105_date::time without time zone), '-2'::integer)
							WHEN e.working_days_8_hr = 1 AND (e.ce105_date::date + 1) = e.ce139_date::date THEN e.ce105_status_time + e.ce139_status_time
							ELSE (e.working_days_8_hr * 28800)::numeric + e.ce105_status_time + e.ce139_status_time
						END AS total_working_hrs
				from
				(
					--SELECT d.ec_id,d.ce104_date,d.ce110_date,d.total_working_days,d.working_days_8_hr,--Kaveri_1_changes 
					SELECT d.applicationnumber,d.ce105_date,d.ce139_date,d.total_working_days,d.working_days_8_hr,--Kaveri_1_changes 
					CASE
						WHEN "substring"(d.ce105_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
						WHEN d.ce105_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce105_status_time
					END AS ce105_status_time,
					CASE
						WHEN "substring"(d.ce139_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
						WHEN d.ce139_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
						ELSE d.ce139_status_time
					END AS ce139_status_time	
					FROM
					(
						--SELECT c.ec_id,c.ce104_date,c.ce110_date,c.total_working_days,c.ce104_status_time,c.ce110_status_time,--Kaveri_1_changes 
						SELECT c.applicationnumber,c.ce105_date,c.ce139_date,c.total_working_days,c.ce105_status_time,c.ce139_status_time,--Kaveri_1_changes 
						CASE
							WHEN c.total_working_days > 2 THEN c.total_working_days - 2
							WHEN c.total_working_days = 2 AND c.ce105_date::date <> c.ce139_date::date THEN 1
							ELSE 0
						END AS working_days_8_hr
						FROM 
						( 	
							--SELECT --b.ec_id,b.ce104_date,b.ce110_date --Kaveri_1_changes 
							SELECT b.applicationnumber,b.ce105_date,b.ce139_date,----Kaveri_1_changes 
							kaveri_analytics.fn_total_working_days(b.ce105_date::date, b.ce139_date::date) AS total_working_days,
							round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce105_date::time without time zone), '-2'::integer) AS ce105_status_time,
							round(EXTRACT(epoch FROM b.ce139_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce139_status_time
							FROM 
							(	--Kaveri_1_changes starts
								/*select t.ec_id,ce110_date,d.submitteddatetime as ce104_date,t.kaverisrocode
								from
								(	select distinct a.ecid  as ec_id,a.signeddatetime as ce110_date,a.kaverisrocode from
									kaveri.ec_applicationdetails a 
									join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
									where b.currentstatus='CE110'
									and date(a.signeddatetime) =var_date
									and a.propertytypeid in (17,18) and  a.isbefore2004='True'
									and a.kaverisrocode=var_rec.srocode 
								)t
								join kaveri.ec_applicationdetails d on t.ec_id=d.ecid*/
								
								select t.applicationnumber,t.ce139_date,max(d.crtdt) as ce105_date,t.kaverisrocode
								from
								(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce139_date,a.kaverisrocode  from
											kaveri.ec_applicationdetails a 
											join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
											join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE139'
											where b.currentstatus in ('CE139','CE140','CE110')
											and a.propertytypeid in (17,18) and a.isbefore2004='False'
											and a.kaverisrocode=var_rec.srocode 
											group by a.applicationnumber,a.kaverisrocode
											having max(date(c.crtdt)) between var_begin_date and var_date
 		
								)t
								join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE105' and t.kaverisrocode=d.srocode
								group by t.applicationnumber,t.ce139_date,t.kaverisrocode
								
								--Kaveri_1_changes ends
							)b
						)c
					)d
				)e
			)f;
		else
			raise notice 'sro starts with CE104';
			SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_prepare_ec
			FROM 	
			(	
				SELECT  e.applicationnumber,e.ce104_date,e.ce139_date,e.total_working_days,e.working_days_8_hr,e.ce104_status_time,e.ce139_status_time,
						CASE
							WHEN e.working_days_8_hr = 0 THEN 0
							WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce139_date::date THEN 0
							ELSE e.working_days_8_hr * 28800
						END AS actual_working_hours,
						CASE
							WHEN e.working_days_8_hr = 0 AND e.ce104_date::date <> e.ce139_date::date THEN e.ce104_status_time + e.ce139_status_time
							WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce139_date::time without time zone - e.ce104_date::time without time zone), '-2'::integer)
							WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce139_date::date THEN e.ce104_status_time + e.ce139_status_time
							ELSE (e.working_days_8_hr * 28800)::numeric + e.ce104_status_time + e.ce139_status_time
						END AS total_working_hrs
				from
				(
					SELECT d.applicationnumber,d.ce104_date,d.ce139_date,d.total_working_days,d.working_days_8_hr,
					CASE
						WHEN "substring"(d.ce104_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
						WHEN d.ce104_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce104_status_time
					END AS ce104_status_time,
					CASE
						WHEN "substring"(d.ce139_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
						WHEN d.ce139_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
						ELSE d.ce139_status_time
					END AS ce139_status_time	
					FROM
					(
						SELECT c.applicationnumber,c.ce104_date,c.ce139_date,c.total_working_days,c.ce104_status_time,c.ce139_status_time,
						CASE
							WHEN c.total_working_days > 2 THEN c.total_working_days - 2
							WHEN c.total_working_days = 2 AND c.ce104_date::date <> c.ce139_date::date THEN 1
							ELSE 0
						END AS working_days_8_hr
						FROM 
						( 	
							SELECT b.applicationnumber,b.ce104_date,b.ce139_date,
							kaveri_analytics.fn_total_working_days(b.ce104_date::date, b.ce139_date::date) AS total_working_days,
							round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce104_date::time without time zone), '-2'::integer) AS ce104_status_time,
							round(EXTRACT(epoch FROM b.ce139_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce139_status_time
							FROM 
							(
								--Kaveri_1_changes starts
								/*select t.ec_id,ce110_date,d.submitteddatetime as ce104_date,t.kaverisrocode
								from
								(	select distinct a.ecid  as ec_id,a.signeddatetime as ce110_date,a.kaverisrocode from
									kaveri.ec_applicationdetails a 
									join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
									where b.currentstatus='CE110'
									and date(a.signeddatetime) =var_date
									and a.propertytypeid in (17,18) and  a.isbefore2004='True'
									and a.kaverisrocode=var_rec.srocode 
								)t
								join kaveri.ec_applicationdetails d on t.ec_id=d.ecid*/
								
								select t.applicationnumber,t.ce139_date,max(d.crtdt) as ce104_date,t.kaverisrocode
								from
								(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt) as ce139_date,a.kaverisrocode  from
											kaveri.ec_applicationdetails a 
											join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber
											join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE139'
											where b.currentstatus IN ('CE139','CE140','CE110')
											and a.propertytypeid in (17,18) and  
											a.isbefore2004='False'
											and a.kaverisrocode=var_rec.srocode 
											group by a.applicationnumber,a.kaverisrocode 
											having max(date(c.crtdt)) between var_begin_date and var_date
 		
								)t
								join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE104' and t.kaverisrocode=d.srocode
								group by t.applicationnumber,t.ce139_date,t.kaverisrocode
								
								--Kaveri_1_changes ends
							)b
						)c
					)d
				)e
			)f;
		end if;
		raise notice 'ALL agriculture -after 2004-Time taken to Prepare the EC  :%',var_tt_prepare_ec;
		-----------------------------------------Time taken to Verify the EC (Step 3)-------------------------------------------------------
		raise notice 'ALL agriculture -after 2004-Time taken to Verify the EC   :%',var_tt_verify_ec;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_verify_ec
		FROM 	
		(	
			SELECT  e.applicationnumber,e.ce139_date,e.ce140_date,e.total_working_days,e.working_days_8_hr,e.ce139_status_time,e.ce140_status_time,
					CASE
						WHEN e.working_days_8_hr = 0 THEN 0
						WHEN e.working_days_8_hr = 1 AND (e.ce139_date::date + 1) = e.ce140_date::date THEN 0
						ELSE e.working_days_8_hr * 28800
					END AS actual_working_hours,
					CASE
						WHEN e.working_days_8_hr = 0 AND e.ce139_date::date <> e.ce140_date::date THEN e.ce139_status_time + e.ce140_status_time
						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce140_date::time without time zone - e.ce139_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce139_date::date + 1) = e.ce140_date::date THEN e.ce139_status_time + e.ce140_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce139_status_time + e.ce140_status_time
					END AS total_working_hrs
			from
			(
				SELECT d.applicationnumber,d.ce139_date,d.ce140_date,d.total_working_days,d.working_days_8_hr,
				CASE
					WHEN "substring"(d.ce139_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce139_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce139_status_time
				END AS ce139_status_time,
				CASE
					WHEN "substring"(d.ce140_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce140_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce140_status_time
				END AS ce140_status_time	
				FROM
				(
					SELECT c.applicationnumber,c.ce139_date,c.ce140_date,c.total_working_days,c.ce139_status_time,c.ce140_status_time,
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce139_date::date <> c.ce140_date::date THEN 1
						ELSE 0
					END AS working_days_8_hr
					FROM 
					( 	
						SELECT b.applicationnumber,b.ce139_date,b.ce140_date,
						kaveri_analytics.fn_total_working_days(b.ce139_date::date, b.ce140_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce139_date::time without time zone), '-2'::integer) AS ce139_status_time,
						round(EXTRACT(epoch FROM b.ce140_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce140_status_time
						FROM 
						(
							select t.applicationnumber,t.ce140_date,max(d.crtdt) as ce139_date,t.kaverisrocode
							from
							(	select distinct a.applicationnumber  as applicationnumber,max(c.crtdt)  as ce140_date,a.kaverisrocode 
								from  kaveri.ec_applicationdetails a 
								join kaveri.applicantapplicationdetails b on a.applicationnumber=b.applicationnumber 
								join kaveri.applicationaudit c on a.applicationnumber=c.applicationnumber and c.wrkflowstatusid='CE140'
								where b.currentstatus in ('CE140','CE110')
								and a.propertytypeid in (17,18) and a.isbefore2004='False'
								and a.kaverisrocode=var_rec.srocode
								group by a.applicationnumber,a.kaverisrocode 
								having max(date(c.crtdt)) between var_begin_date and var_date
							)t
							join kaveri.applicationaudit d on t.applicationnumber=d.applicationnumber and d.wrkflowstatusid='CE139' and t.kaverisrocode=d.srocode
							group by t.applicationnumber,t.ce140_date,t.kaverisrocode
						)b
					)c
				)d
			)e
		)f;
		raise notice 'ALL agriculture -after 2004-Time taken to Verify the EC   :%',var_tt_verify_ec;
		--------------------------------------Time taken to Approve the EC (Step 4)-----------------------------------------------------------
		raise notice 'ALL agriculture -after 2004-Time taken to Approve the EC :%',var_tt_approve_ec;
		SELECT avg(f.total_working_hrs / 28800::numeric)  into var_tt_approve_ec
		FROM 	
		(	
			SELECT  e.applicationnumber,e.ce140_date,e.ce110_date,e.total_working_days,e.working_days_8_hr,e.ce140_status_time,e.ce110_status_time,
					CASE
						WHEN e.working_days_8_hr = 0 THEN 0
						WHEN e.working_days_8_hr = 1 AND (e.ce140_date::date + 1) = e.ce110_date::date THEN 0
						ELSE e.working_days_8_hr * 28800
					END AS actual_working_hours,
					CASE
						WHEN e.working_days_8_hr = 0 AND e.ce140_date::date <> e.ce110_date::date THEN e.ce140_status_time + e.ce110_status_time
						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce110_date::time without time zone - e.ce140_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce140_date::date + 1) = e.ce110_date::date THEN e.ce140_status_time + e.ce110_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce140_status_time + e.ce110_status_time
					END AS total_working_hrs
			from
			(
				SELECT d.applicationnumber,d.ce140_date,d.ce110_date,d.total_working_days,d.working_days_8_hr,
				CASE
					WHEN "substring"(d.ce140_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce140_date::time without time zone <= '10:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce140_status_time
				END AS ce140_status_time,
				CASE
					WHEN "substring"(d.ce110_status_time::character varying(10)::text, 1, 1) = '-'::text THEN 0::numeric
					WHEN d.ce110_date::time without time zone >= '18:00:00'::time without time zone THEN 28800::numeric
					ELSE d.ce110_status_time
				END AS ce110_status_time	
				FROM
				(
					SELECT c.applicationnumber,c.ce140_date,c.ce110_date,c.total_working_days,c.ce140_status_time,c.ce110_status_time,
					CASE
						WHEN c.total_working_days > 2 THEN c.total_working_days - 2
						WHEN c.total_working_days = 2 AND c.ce140_date::date <> c.ce110_date::date THEN 1
						ELSE 0
