						kaveri_analytics.fn_total_working_days(b.ce140_date::date, b.ce110_date::date) AS total_working_days,
						round(EXTRACT(epoch FROM '18:00:00'::time without time zone - b.ce140_date::time without time zone), '-2'::integer) AS ce140_status_time,
						round(EXTRACT(epoch FROM b.ce110_date::time without time zone - '10:00:00'::time without time zone), '-2'::integer) AS ce110_status_time
						FROM 
						(
							select t.applicationnumber,t.ce110_date,max(d.crtdt) as ce140_date,t.kaverisrocode
