		raise notice 'ALL agriculture -after 2004-Time taken to Approve the EC :%',var_tt_approve_ec;
		
		if var_date=var_begin_date
		then
			raise notice 'begining of the month so deleting previous month records';
			delete from kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active where financial_year_id=var_fin_year_id and srocode=var_rec.srocode and month_id=var_Month_id_all and propertytype_id_csg=1 and flag_before_2004=2;
