						and c.propertytype_id_csg=2 and c.flag_before_2004=2
					  )as a 
				where b.financial_Year_id=var_fin_year_id and b.month_id=var_Month_id_all and b.srocode=var_rec.srocode and b.propertytype_id_csg=2 and b.flag_before_2004=2;
				RAISE NOTICE 'AFTER UPDATE';
