						WHEN e.working_days_8_hr = 0 THEN round(EXTRACT(epoch FROM e.ce102_date::time without time zone - e.ce104_date::time without time zone), '-2'::integer)
						WHEN e.working_days_8_hr = 1 AND (e.ce104_date::date + 1) = e.ce102_date::date THEN e.ce104_status_time + e.ce102_status_time
						ELSE (e.working_days_8_hr * 28800)::numeric + e.ce104_status_time + e.ce102_status_time
					END AS total_working_hrs
