				var_fin_year_id,
				var_fin_year,
				var_month_id_all,
				var_month_all,
				var_rec.district_code_agri,
				var_rec.district_name_agri,
				var_rec.srocode,
				var_rec.sroname,
				1,
				'Agriculture',
				1,
				COALESCE(var_tt_deliver,0),
				COALESCE(var_tt_allocate_appln,0),
				COALESCE(var_tt_prepare_ec,0),
				COALESCE(var_tt_verify_ec,0),
				COALESCE(var_tt_approve_ec,0)
				);
		end if;
		if var_date=var_financial_year
		then
			RAISE NOTICE 'INSIDE UPDATE';
			BEGIN
				insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_history
				(
					financial_year_id,
					financial_year,
					month_id,
					month_name,
					district_code,
					district_name,
					srocode,
					sroname,
					propertytype_id_csg,
					property_type,
					flag_before_2004,
					time_taken_deliver,
					time_taken_allocate,
					time_taken_prepare_ec,
					time_taken_verify_ec,
					time_taken_approve_ec
				) 
				values
				(
					
					var_fin_year_id,
					var_fin_year,
					var_Month_id_all,
					var_month_all,
					var_rec.district_code_agri,
					var_rec.district_name_agri,
					var_rec.srocode,
					var_rec.sroname,
