						and c.propertytype_id_csg=1 and c.flag_before_2004=1
					  )as a 
				where b.financial_Year_id=var_fin_year_id and b.month_id=var_Month_id_all and b.srocode=var_rec.srocode and b.propertytype_id_csg=1 and b.flag_before_2004=1;
				RAISE NOTICE 'AFTER UPDATE';
			EXCEPTION
