		raise notice 'var_date :%',var_date;
		raise notice 'var_tt_deliver :%',var_tt_deliver;
		raise notice 'var_tt_allocate_appln :%',var_tt_allocate_appln;
		raise notice 'var_tt_prepare_ec :%',var_tt_prepare_ec;
		raise notice 'var_tt_verify_ec :%',var_tt_verify_ec;
		raise notice 'var_tt_approve_ec :%',var_tt_approve_ec;
		if var_date=var_begin_date
		then
			raise notice 'begining of thr month so deleting previous month records';
			delete from kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active where financial_year_id=var_fin_year_id and srocode=var_rec.srocode and month_id=var_Month_id and propertytype_id_csg=2 and flag_before_2004=1;
			insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active
			(
				date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				flag_before_2004,
				time_taken_deliver,
				time_taken_allocate,
				time_taken_prepare_ec,
				time_taken_verify_ec,
				time_taken_approve_ec
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_Month_id,
				var_monthname,
				var_rec.district_code_non_agri,
				var_rec.district_name_non_agri,
				var_rec.srocode,
				var_rec.sroname,
				2,
				'Non Agriculture',
				1,
				COALESCE(var_tt_deliver,0),
				COALESCE(var_tt_allocate_appln,0),
				COALESCE(var_tt_prepare_ec,0),
				COALESCE(var_tt_verify_ec,0),
				COALESCE(var_tt_approve_ec,0)
			);
			
		else
			insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_active
			(
				date,
				financial_year_id,
				financial_year,
				month_id,
				month_name,
				district_code,
				district_name,
				srocode,
				sroname,
				propertytype_id_csg,
				property_type,
				flag_before_2004,
				time_taken_deliver,
				time_taken_allocate,
				time_taken_prepare_ec,
				time_taken_verify_ec,
				time_taken_approve_ec
			) 
			values
			(
				var_date,
				var_fin_year_id,
				var_fin_year,
				var_Month_id,
				var_monthname,
				var_rec.district_code_non_agri,
				var_rec.district_name_non_agri,
				var_rec.srocode,
				var_rec.sroname,
				2,
				'Non Agriculture',
				1,
				COALESCE(var_tt_deliver,0),
				COALESCE(var_tt_allocate_appln,0),
				COALESCE(var_tt_prepare_ec,0),
				COALESCE(var_tt_verify_ec,0),
				COALESCE(var_tt_approve_ec,0)
				);
		end if;
		if var_date=var_begin_date
		then
			RAISE NOTICE 'INSIDE UPDATE';
			BEGIN
				insert into kaveri_analytics.tbl_kaveri_kpi_ec_time_calculation_history
				(
					financial_year_id,
					financial_year,
					month_id,
					month_name,
					district_code,
					district_name,
					srocode,
					sroname,
					propertytype_id_csg,
					property_type,
					flag_before_2004,
