    tbl_kaveri1_doc_reg_details.districtname AS district_name,
    tbl_kaveri1_doc_reg_details.property_type,
    count(DISTINCT tbl_kaveri1_doc_reg_details.id) AS applications_registered,
    0 AS avg_days_taken
   FROM kaveri_analytics.tbl_kaveri1_doc_reg_details
  WHERE ((tbl_kaveri1_doc_reg_details.property_type)::text = 'Non Agriculture'::text)
  GROUP BY tbl_kaveri1_doc_reg_details.kaveri_v1_v2, tbl_kaveri1_doc_reg_details.financial_year, tbl_kaveri1_doc_reg_details.monthname, tbl_kaveri1_doc_reg_details.srocode, tbl_kaveri1_doc_reg_details.sroname, tbl_kaveri1_doc_reg_details.districtcode, tbl_kaveri1_doc_reg_details.districtname, tbl_kaveri1_doc_reg_details.property_type, 0::integer;


