--
-- Name: vw_applications_total_revenue_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_applications_total_revenue_agriculture AS
 SELECT 2 AS kaveri_v1_v2,
    x.financial_year,
    x.monthname,
    x.srocode,
    x.sroname,
    x.district_code,
    x.district_name,
    x.property_type,
    x.regarticlecode,
    x.articlenamee,
    count(DISTINCT x.applicationnumber) AS total_applications,
    sum(x.stamp_duty) AS stamp_duty,
    sum(x.registration_fee) AS registration_fee,
    sum(x.total_revenue) AS total_revenue
   FROM ( SELECT v.applicationnumber,
            v.financial_year,
            v.srocode,
            m.sroname,
            m.district_code_agri AS district_code,
            m.district_name_agri AS district_name,
            v.monthname,
            v.property_type,
            v.regarticlecode,
            v.articlenamee,
            v.stamp_duty,
            v.registration_fee,
            v.total_revenue
           FROM ( SELECT u.applicationnumber,
                        CASE
                            WHEN (EXTRACT(month FROM u.crtdt) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM u.crtdt) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM u.crtdt))::character varying)::text, 3, 2))
                            WHEN (EXTRACT(month FROM u.crtdt) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM u.crtdt), '-', (("substring"(((EXTRACT(year FROM u.crtdt))::character varying)::text, 3, 2))::integer + 1))
                            ELSE NULL::text
                        END AS financial_year,
                    TRIM(TRAILING FROM to_char(u.crtdt, 'Month'::text)) AS monthname,
                    u.srocode,
                    u.property_type,
                    u.regarticlecode,
                    u.articlenamee,
                    u.stamp_duty,
                    u.registration_fee,
                    (u.stamp_duty + u.registration_fee) AS total_revenue
                   FROM ( SELECT DISTINCT t.applicationnumber,
                            t.srocode,
                            t.property_type,
                            sum(
                                CASE
                                    WHEN (t.feerulecode = 36) THEN t.amountpaid
                                    ELSE NULL::numeric
                                END) AS stamp_duty,
                            sum(
                                CASE
                                    WHEN (t.feerulecode = 1) THEN t.amountpaid
                                    ELSE NULL::numeric
                                END) AS registration_fee,
                            t.regarticlecode,
                            t.articlenamee,
                            t.crtdt
                           FROM ( SELECT DISTINCT a.applicationnumber,
                                    a.srocode,
                                    b.feerulecode,
                                    b.amountpaid,
                                    c.propertytypeid,
CASE
 WHEN (c.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
 ELSE NULL::text
END AS property_type,
                                    c.regarticlecode,
                                    x_1.articlenamee,
                                    d.ackdatetime AS crtdt
                                   FROM ((((kaveri.applicantapplicationdetails a
                                     JOIN kaveri.feesrequired b ON (((a.applicationnumber)::text = (b.applicationnumber)::text)))
                                     JOIN kaveri.propertymaster c ON (((a.applicationnumber)::text = (c.applicationnumber)::text)))
                                     JOIN kaveri.documentmaster d ON (((a.applicationnumber)::text = (d.applicationnumber)::text)))
                                     JOIN kaveri.registrationarticles x_1 ON ((c.regarticlecode = x_1.regarticlecode)))
                                  WHERE ((a.applicationtypeid = ANY (ARRAY[1, 2])) AND ((a.currentstatus)::text = 'CD120'::text) AND (a.bookid = 1) AND (c.propertytypeid <> 1001) AND (b.feerulecode = ANY (ARRAY[1, 36])) AND (c.propertytypeid = ANY (ARRAY[17, 18])))) t
                          GROUP BY t.srocode, t.property_type, t.applicationnumber, t.regarticlecode, t.articlenamee, t.crtdt) u) v,
            kaveri_analytics.tbl_district_sro_mapping m
          WHERE (v.srocode = m.srocode)) x
  GROUP BY x.financial_year, x.srocode, x.sroname, x.district_code, x.district_name, x.monthname, x.property_type, x.regarticlecode, x.articlenamee
UNION
 SELECT tbl_kaveri1_doc_reg_details.kaveri_v1_v2,
    tbl_kaveri1_doc_reg_details.financial_year,
    tbl_kaveri1_doc_reg_details.monthname,
    tbl_kaveri1_doc_reg_details.srocode,
    tbl_kaveri1_doc_reg_details.sroname,
    tbl_kaveri1_doc_reg_details.districtcode AS district_code,
    tbl_kaveri1_doc_reg_details.districtname AS district_name,
    tbl_kaveri1_doc_reg_details.property_type,
    tbl_kaveri1_doc_reg_details.regarticlecode,
    tbl_kaveri1_doc_reg_details.regarticlename AS articlenamee,
    count(DISTINCT tbl_kaveri1_doc_reg_details.id) AS total_applications,
    sum(tbl_kaveri1_doc_reg_details.stampdutycollected) AS stamp_duty,
    sum(tbl_kaveri1_doc_reg_details.regfeescollected) AS registration_fee,
    sum((tbl_kaveri1_doc_reg_details.stampdutycollected + tbl_kaveri1_doc_reg_details.regfeescollected)) AS total_revenue
   FROM kaveri_analytics.tbl_kaveri1_doc_reg_details
  WHERE ((tbl_kaveri1_doc_reg_details.property_type)::text = 'Agriculture'::text)
  GROUP BY tbl_kaveri1_doc_reg_details.kaveri_v1_v2, tbl_kaveri1_doc_reg_details.financial_year, tbl_kaveri1_doc_reg_details.monthname, tbl_kaveri1_doc_reg_details.srocode, tbl_kaveri1_doc_reg_details.sroname, tbl_kaveri1_doc_reg_details.districtcode, tbl_kaveri1_doc_reg_details.districtname, tbl_kaveri1_doc_reg_details.property_type, tbl_kaveri1_doc_reg_details.regarticlecode, tbl_kaveri1_doc_reg_details.regarticlename;


