--
-- Name: vw_avg_time_approve_payment_wrk_days_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_avg_time_approve_payment_wrk_days_agriculture AS
 SELECT w.applicationnumber,
    w.financial_year,
    w.monthname,
    w.property_type,
    w.srocode,
    w.sroname,
    w.district_code,
    w.district_name,
    w.crtdt_cd102,
    w.crtdt_cd106,
    w.total_working_days,
    w.working_days_8_hr,
    w.cd102_status_time,
    w.cd106_status_time,
    w.actual_working_hours,
    w.total_working_hrs,
    (w.total_working_hrs / (28800)::numeric) AS total_days
   FROM ( SELECT v.applicationnumber,
            v.financial_year,
            v.monthname,
            v.property_type,
            v.srocode,
            v.sroname,
            v.district_code,
            v.district_name,
            v.crtdt_cd102,
            v.crtdt_cd106,
            v.total_working_days,
            v.working_days_8_hr,
            v.cd102_status_time,
            v.cd106_status_time,
                CASE
                    WHEN (v.working_days_8_hr = 0) THEN 0
                    WHEN ((v.working_days_8_hr = 1) AND (((v.crtdt_cd102)::date + 1) = (v.crtdt_cd106)::date)) THEN 0
                    ELSE (v.working_days_8_hr * 28800)
                END AS actual_working_hours,
                CASE
                    WHEN ((v.working_days_8_hr = 0) AND ((v.crtdt_cd102)::date <> (v.crtdt_cd106)::date)) THEN (v.cd102_status_time + v.cd106_status_time)
                    WHEN (v.working_days_8_hr = 0) THEN round(EXTRACT(epoch FROM ((v.crtdt_cd106)::time without time zone - (v.crtdt_cd102)::time without time zone)), '-2'::integer)
                    WHEN ((v.working_days_8_hr = 1) AND (((v.crtdt_cd102)::date + 1) = (v.crtdt_cd106)::date)) THEN (v.cd102_status_time + v.cd106_status_time)
                    ELSE ((((v.working_days_8_hr * 28800))::numeric + v.cd102_status_time) + v.cd106_status_time)
                END AS total_working_hrs
           FROM ( SELECT u.applicationnumber,
                    u.financial_year,
                    u.monthname,
                    u.property_type,
                    u.srocode,
                    u.sroname,
                    u.district_code,
                    u.district_name,
                    u.crtdt_cd102,
                    u.crtdt_cd106,
                    u.total_working_days,
                    u.working_days_8_hr,
                        CASE
                            WHEN ("substring"(((u.cd102_status_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.crtdt_cd102)::time without time zone <= '10:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.cd102_status_time
                        END AS cd102_status_time,
                        CASE
                            WHEN ("substring"(((u.cd106_status_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.crtdt_cd106)::time without time zone >= '18:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.cd106_status_time
                        END AS cd106_status_time
                   FROM ( SELECT t.applicationnumber,
                            t.financial_year,
                            t.monthname,
                            t.property_type,
                            t.srocode,
                            t.sroname,
                            t.district_code,
                            t.district_name,
                            t.crtdt_cd102,
                            t.crtdt_cd106,
                            t.total_working_days,
                            t.cd102_status_time,
                            t.cd106_status_time,
                                CASE
                                    WHEN (t.total_working_days > 2) THEN (t.total_working_days - 2)
                                    WHEN ((t.total_working_days = 2) AND ((t.crtdt_cd102)::date <> (t.crtdt_cd106)::date)) THEN 1
                                    ELSE 0
                                END AS working_days_8_hr
                           FROM ( SELECT vw_avg_time_approve_payment_agriculture.applicationnumber,
                                    vw_avg_time_approve_payment_agriculture.financial_year,
                                    vw_avg_time_approve_payment_agriculture.monthname,
                                    vw_avg_time_approve_payment_agriculture.property_type,
                                    vw_avg_time_approve_payment_agriculture.srocode,
                                    vw_avg_time_approve_payment_agriculture.sroname,
                                    vw_avg_time_approve_payment_agriculture.district_code,
                                    vw_avg_time_approve_payment_agriculture.district_name,
                                    vw_avg_time_approve_payment_agriculture.crtdt_cd102,
                                    vw_avg_time_approve_payment_agriculture.crtdt_cd106,
                                    kaveri_analytics.fn_total_working_days((vw_avg_time_approve_payment_agriculture.crtdt_cd102)::date, (vw_avg_time_approve_payment_agriculture.crtdt_cd106)::date) AS total_working_days,
                                    round(EXTRACT(epoch FROM ('18:00:00'::time without time zone - (vw_avg_time_approve_payment_agriculture.crtdt_cd102)::time without time zone)), '-2'::integer) AS cd102_status_time,
                                    round(EXTRACT(epoch FROM ((vw_avg_time_approve_payment_agriculture.crtdt_cd106)::time without time zone - '10:00:00'::time without time zone)), '-2'::integer) AS cd106_status_time
                                   FROM kaveri_analytics.vw_avg_time_approve_payment_agriculture) t) u) v) w;


ALTER TABLE kaveri_analytics.vw_avg_time_approve_payment_wrk_days_agriculture OWNER TO postgres;

