                            t.district_name,
                            t.crtdt_cd102,
                            t.crtdt_cd106,
                            t.total_working_days,
                            t.cd102_status_time,
                            t.cd106_status_time,
                                CASE
                                    WHEN (t.total_working_days > 2) THEN (t.total_working_days - 2)
                                    WHEN ((t.total_working_days = 2) AND ((t.crtdt_cd102)::date <> (t.crtdt_cd106)::date)) THEN 1
                                    ELSE 0
                                END AS working_days_8_hr
                           FROM ( SELECT vw_avg_time_approve_payment_non_agriculture.applicationnumber,
                                    vw_avg_time_approve_payment_non_agriculture.financial_year,
                                    vw_avg_time_approve_payment_non_agriculture.monthname,
                                    vw_avg_time_approve_payment_non_agriculture.property_type,
                                    vw_avg_time_approve_payment_non_agriculture.srocode,
                                    vw_avg_time_approve_payment_non_agriculture.sroname,
                                    vw_avg_time_approve_payment_non_agriculture.district_code,
                                    vw_avg_time_approve_payment_non_agriculture.district_name,
                                    vw_avg_time_approve_payment_non_agriculture.crtdt_cd102,
                                    vw_avg_time_approve_payment_non_agriculture.crtdt_cd106,
                                    kaveri_analytics.fn_total_working_days((vw_avg_time_approve_payment_non_agriculture.crtdt_cd102)::date, (vw_avg_time_approve_payment_non_agriculture.crtdt_cd106)::date) AS total_working_days,
                                    round(EXTRACT(epoch FROM ('18:00:00'::time without time zone - (vw_avg_time_approve_payment_non_agriculture.crtdt_cd102)::time without time zone)), '-2'::integer) AS cd102_status_time,
                                    round(EXTRACT(epoch FROM ((vw_avg_time_approve_payment_non_agriculture.crtdt_cd106)::time without time zone - '10:00:00'::time without time zone)), '-2'::integer) AS cd106_status_time
                                   FROM kaveri_analytics.vw_avg_time_approve_payment_non_agriculture) t) u) v) w;


