--
-- Name: vw_avg_time_approve_registration_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_avg_time_approve_registration_agriculture AS
 SELECT x.applicationnumber,
        CASE
            WHEN (EXTRACT(month FROM x.crtdt_cd120) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM x.crtdt_cd120) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM x.crtdt_cd120))::character varying)::text, 3, 2))
            WHEN (EXTRACT(month FROM x.crtdt_cd120) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM x.crtdt_cd120), '-', (("substring"(((EXTRACT(year FROM x.crtdt_cd120))::character varying)::text, 3, 2))::integer + 1))
            ELSE NULL::text
        END AS financial_year,
    TRIM(TRAILING FROM to_char(x.crtdt_cd120, 'Month'::text)) AS monthname,
    x.property_type,
    x.srocode,
    m.sroname,
    m.district_code_agri AS district_code,
    m.district_name_agri AS district_name,
    x.crtdt_cd108,
    x.crtdt_cd120,
    EXTRACT(epoch FROM (x.crtdt_cd120 - x.crtdt_cd108)) AS difference,
    age(x.crtdt_cd120, x.crtdt_cd108) AS time_difference,
    (EXTRACT(epoch FROM (x.crtdt_cd120 - x.crtdt_cd108)) / (86400)::numeric) AS days
   FROM ( SELECT t.applicationnumber,
            t.srocode,
            t.property_type,
            max(t.appointmentdate) AS crtdt_cd108,
            max(t.ackdatetime) AS crtdt_cd120
           FROM ( SELECT DISTINCT a.applicationnumber,
                    a.srocode,
                    b.propertytypeid,
                        CASE
                            WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
                            ELSE NULL::text
                        END AS property_type,
                    c.appointmentdate,
                    d.ackdatetime
                   FROM (((kaveri.applicantapplicationdetails a
                     JOIN kaveri.propertymaster b ON (((a.applicationnumber)::text = (b.applicationnumber)::text)))
                     JOIN kaveri.appointmentmaster c ON (((a.applicationnumber)::text = (c.applicationnumber)::text)))
                     JOIN kaveri.documentmaster d ON (((a.applicationnumber)::text = (d.applicationnumber)::text)))
                  WHERE ((a.applicationtypeid = ANY (ARRAY[1, 2])) AND (a.bookid = 1) AND (b.propertytypeid <> 1001) AND (b.propertytypeid = ANY (ARRAY[17, 18])) AND ((a.currentstatus)::text = 'CD120'::text) AND (c.inserteddatetime = ( SELECT max(appointmentmaster.inserteddatetime) AS max
                           FROM kaveri.appointmentmaster
                          WHERE ((appointmentmaster.applicationnumber)::text = (a.applicationnumber)::text))))) t
          GROUP BY t.applicationnumber, t.srocode, t.property_type) x,
    kaveri_analytics.tbl_district_sro_mapping m
  WHERE (x.srocode = m.srocode);


ALTER TABLE kaveri_analytics.vw_avg_time_approve_registration_agriculture OWNER TO postgres;

