--
-- Name: vw_avg_time_receiving_appointment_wrk_days_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_avg_time_receiving_appointment_wrk_days_agriculture AS
 SELECT w.applicationnumber,
    w.financial_year,
    w.monthname,
    w.property_type,
    w.srocode,
    w.sroname,
    w.district_code,
    w.district_name,
    w.inserted_date,
    w.appointment_date,
    w.total_working_days,
    w.working_days_8_hr,
    w.inserted_date_time,
    w.appointment_date_time,
    w.actual_working_hours,
    w.total_working_hrs,
    (w.total_working_hrs / (28800)::numeric) AS total_days
   FROM ( SELECT v.applicationnumber,
            v.financial_year,
            v.monthname,
            v.property_type,
            v.srocode,
            v.sroname,
            v.district_code,
            v.district_name,
            v.inserted_date,
            v.appointment_date,
            v.total_working_days,
            v.working_days_8_hr,
            v.inserted_date_time,
            v.appointment_date_time,
                CASE
                    WHEN (v.working_days_8_hr = 0) THEN 0
                    WHEN ((v.working_days_8_hr = 1) AND (((v.inserted_date)::date + 1) = (v.appointment_date)::date)) THEN 0
                    ELSE (v.working_days_8_hr * 28800)
                END AS actual_working_hours,
                CASE
                    WHEN ((v.working_days_8_hr = 0) AND ((v.inserted_date)::date <> (v.appointment_date)::date)) THEN (v.inserted_date_time + v.appointment_date_time)
                    WHEN (v.working_days_8_hr = 0) THEN round(EXTRACT(epoch FROM ((v.appointment_date)::time without time zone - (v.inserted_date)::time without time zone)), '-2'::integer)
                    WHEN ((v.working_days_8_hr = 1) AND (((v.inserted_date)::date + 1) = (v.appointment_date)::date)) THEN (v.inserted_date_time + v.appointment_date_time)
                    ELSE ((((v.working_days_8_hr * 28800))::numeric + v.inserted_date_time) + v.appointment_date_time)
                END AS total_working_hrs
           FROM ( SELECT u.applicationnumber,
                    u.financial_year,
                    u.monthname,
                    u.property_type,
                    u.srocode,
                    u.sroname,
                    u.district_code,
                    u.district_name,
                    u.inserted_date,
                    u.appointment_date,
                    u.total_working_days,
                    u.working_days_8_hr,
                        CASE
                            WHEN ("substring"(((u.inserted_date_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.inserted_date)::time without time zone <= '10:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.inserted_date_time
                        END AS inserted_date_time,
                        CASE
                            WHEN ("substring"(((u.appointment_date_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.appointment_date)::time without time zone >= '18:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.appointment_date_time
                        END AS appointment_date_time
                   FROM ( SELECT t.applicationnumber,
                            t.financial_year,
                            t.monthname,
                            t.property_type,
                            t.srocode,
                            t.sroname,
                            t.district_code,
                            t.district_name,
                            t.inserted_date,
                            t.appointment_date,
                            t.total_working_days,
                            t.inserted_date_time,
                            t.appointment_date_time,
                                CASE
                                    WHEN (t.total_working_days > 2) THEN (t.total_working_days - 2)
                                    WHEN ((t.total_working_days = 2) AND ((t.inserted_date)::date <> (t.appointment_date)::date)) THEN 1
                                    ELSE 0
                                END AS working_days_8_hr
                           FROM ( SELECT vw_avg_time_receiving_appointment_agriculture.applicationnumber,
                                    vw_avg_time_receiving_appointment_agriculture.financial_year,
                                    vw_avg_time_receiving_appointment_agriculture.monthname,
                                    vw_avg_time_receiving_appointment_agriculture.property_type,
                                    vw_avg_time_receiving_appointment_agriculture.srocode,
                                    vw_avg_time_receiving_appointment_agriculture.sroname,
                                    vw_avg_time_receiving_appointment_agriculture.district_code,
                                    vw_avg_time_receiving_appointment_agriculture.district_name,
                                    vw_avg_time_receiving_appointment_agriculture.inserted_date,
                                    vw_avg_time_receiving_appointment_agriculture.appointment_date,
                                    kaveri_analytics.fn_total_working_days((vw_avg_time_receiving_appointment_agriculture.inserted_date)::date, (vw_avg_time_receiving_appointment_agriculture.appointment_date)::date) AS total_working_days,
                                    round(EXTRACT(epoch FROM ('18:00:00'::time without time zone - (vw_avg_time_receiving_appointment_agriculture.inserted_date)::time without time zone)), '-2'::integer) AS inserted_date_time,
                                    round(EXTRACT(epoch FROM ((vw_avg_time_receiving_appointment_agriculture.appointment_date)::time without time zone - '10:00:00'::time without time zone)), '-2'::integer) AS appointment_date_time
                                   FROM kaveri_analytics.vw_avg_time_receiving_appointment_agriculture) t) u) v) w;


ALTER TABLE kaveri_analytics.vw_avg_time_receiving_appointment_wrk_days_agriculture OWNER TO postgres;

