                            WHEN ("substring"(((u.inserted_date_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.inserted_date)::time without time zone <= '10:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.inserted_date_time
                        END AS inserted_date_time,
                        CASE
                            WHEN ("substring"(((u.appointment_date_time)::character varying(10))::text, 1, 1) = '-'::text) THEN (0)::numeric
                            WHEN ((u.appointment_date)::time without time zone >= '18:00:00'::time without time zone) THEN (28800)::numeric
                            ELSE u.appointment_date_time
                        END AS appointment_date_time
                   FROM ( SELECT t.applicationnumber,
                            t.financial_year,
                            t.monthname,
                            t.property_type,
                            t.srocode,
                            t.sroname,
                            t.district_code,
                            t.district_name,
                            t.inserted_date,
                            t.appointment_date,
                            t.total_working_days,
                            t.inserted_date_time,
                            t.appointment_date_time,
                                CASE
                                    WHEN (t.total_working_days > 2) THEN (t.total_working_days - 2)
                                    WHEN ((t.total_working_days = 2) AND ((t.inserted_date)::date <> (t.appointment_date)::date)) THEN 1
                                    ELSE 0
                                END AS working_days_8_hr
                           FROM ( SELECT vw_avg_time_receiving_appointment_non_agriculture.applicationnumber,
                                    vw_avg_time_receiving_appointment_non_agriculture.financial_year,
                                    vw_avg_time_receiving_appointment_non_agriculture.monthname,
                                    vw_avg_time_receiving_appointment_non_agriculture.property_type,
                                    vw_avg_time_receiving_appointment_non_agriculture.srocode,
                                    vw_avg_time_receiving_appointment_non_agriculture.sroname,
                                    vw_avg_time_receiving_appointment_non_agriculture.district_code,
                                    vw_avg_time_receiving_appointment_non_agriculture.district_name,
                                    vw_avg_time_receiving_appointment_non_agriculture.inserted_date,
                                    vw_avg_time_receiving_appointment_non_agriculture.appointment_date,
                                    kaveri_analytics.fn_total_working_days((vw_avg_time_receiving_appointment_non_agriculture.inserted_date)::date, (vw_avg_time_receiving_appointment_non_agriculture.appointment_date)::date) AS total_working_days,
                                    round(EXTRACT(epoch FROM ('18:00:00'::time without time zone - (vw_avg_time_receiving_appointment_non_agriculture.inserted_date)::time without time zone)), '-2'::integer) AS inserted_date_time,
                                    round(EXTRACT(epoch FROM ((vw_avg_time_receiving_appointment_non_agriculture.appointment_date)::time without time zone - '10:00:00'::time without time zone)), '-2'::integer) AS appointment_date_time
                                   FROM kaveri_analytics.vw_avg_time_receiving_appointment_non_agriculture) t) u) v) w;


