--
-- Name: vw_best_performing_districts_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_best_performing_districts_agriculture AS
 WITH revenue_registrations AS (
         SELECT tbl_kaveri_kpi_details_history.financial_year_id,
            tbl_kaveri_kpi_details_history.financial_year,
            tbl_kaveri_kpi_details_history.month_id,
            tbl_kaveri_kpi_details_history.month_name,
            tbl_kaveri_kpi_details_history.district_code,
            tbl_kaveri_kpi_details_history.district_name,
            tbl_kaveri_kpi_details_history.propertytype_id_csg,
            tbl_kaveri_kpi_details_history.property_type,
            tbl_kaveri_kpi_details_history.total_doc_reg AS applications_registered,
            tbl_kaveri_kpi_details_history.appln_with_sro AS total_documents,
            (sum(tbl_kaveri_kpi_details_history.total_doc_reg) / sum(tbl_kaveri_kpi_details_history.appln_with_sro)) AS registration_percentage,
            sum((tbl_kaveri_kpi_details_history.stamp_duty + tbl_kaveri_kpi_details_history.registration_fee)) AS amount_paid
           FROM kaveri_analytics.tbl_kaveri_kpi_details_history
          WHERE ((tbl_kaveri_kpi_details_history.propertytype_id_csg = 1) AND (tbl_kaveri_kpi_details_history.total_doc_reg <> 0))
          GROUP BY tbl_kaveri_kpi_details_history.financial_year_id, tbl_kaveri_kpi_details_history.financial_year, tbl_kaveri_kpi_details_history.month_id, tbl_kaveri_kpi_details_history.month_name, tbl_kaveri_kpi_details_history.district_code, tbl_kaveri_kpi_details_history.district_name, tbl_kaveri_kpi_details_history.propertytype_id_csg, tbl_kaveri_kpi_details_history.property_type, tbl_kaveri_kpi_details_history.total_doc_reg, tbl_kaveri_kpi_details_history.appln_with_sro
        ), avg_time AS (
         SELECT tbl_kaveri_kpi_time_calculation_history.financial_year_id,
            tbl_kaveri_kpi_time_calculation_history.financial_year,
            tbl_kaveri_kpi_time_calculation_history.month_id,
            tbl_kaveri_kpi_time_calculation_history.month_name,
            tbl_kaveri_kpi_time_calculation_history.district_code,
            tbl_kaveri_kpi_time_calculation_history.district_name,
            tbl_kaveri_kpi_time_calculation_history.propertytype_id_csg,
            tbl_kaveri_kpi_time_calculation_history.property_type,
            avg(tbl_kaveri_kpi_time_calculation_history.avg_tt_register_the_doc) AS total_days
           FROM kaveri_analytics.tbl_kaveri_kpi_time_calculation_history
          WHERE (tbl_kaveri_kpi_time_calculation_history.propertytype_id_csg = 1)
          GROUP BY tbl_kaveri_kpi_time_calculation_history.financial_year_id, tbl_kaveri_kpi_time_calculation_history.financial_year, tbl_kaveri_kpi_time_calculation_history.month_id, tbl_kaveri_kpi_time_calculation_history.month_name, tbl_kaveri_kpi_time_calculation_history.district_code, tbl_kaveri_kpi_time_calculation_history.district_name, tbl_kaveri_kpi_time_calculation_history.propertytype_id_csg, tbl_kaveri_kpi_time_calculation_history.property_type
        )
 SELECT t.financial_year_id,
    t.financial_year,
    t.month_id,
    t.month_name,
    t.district_code,
    t.district_name,
    t.propertytype_id_csg,
    t.property_type,
    t.applications_registered,
    t.total_documents,
    t.registration_percentage,
    t.amount_paid,
    t.total_days,
    t.revenue_rank,
    t.registrations_rank,
    t.avg_days_rank,
    (((t.revenue_rank + t.registrations_rank) + t.avg_days_rank) / 3) AS total_rank
   FROM ( SELECT r.financial_year_id,
            r.financial_year,
            r.month_id,
            r.month_name,
            r.district_code,
            r.district_name,
            r.propertytype_id_csg,
            r.property_type,
            r.applications_registered,
            r.total_documents,
            r.registration_percentage,
            r.amount_paid,
            a.total_days,
            dense_rank() OVER (PARTITION BY r.month_id ORDER BY r.amount_paid DESC) AS revenue_rank,
            dense_rank() OVER (PARTITION BY r.month_id ORDER BY r.registration_percentage DESC) AS registrations_rank,
            dense_rank() OVER (PARTITION BY r.month_id ORDER BY a.total_days) AS avg_days_rank
           FROM (revenue_registrations r
             JOIN avg_time a ON (((r.financial_year_id = a.financial_year_id) AND ((r.financial_year)::text = (a.financial_year)::text) AND (r.month_id = a.month_id) AND ((r.month_name)::text = (a.month_name)::text) AND (r.district_code = a.district_code) AND ((r.district_name)::text = (a.district_name)::text) AND (r.propertytype_id_csg = a.propertytype_id_csg) AND ((r.property_type)::text = (a.property_type)::text))))) t;


