--
-- Name: vw_calendar; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_calendar AS
 SELECT EXTRACT(isoyear FROM dates_series.datum) AS year_num,
    (to_char((dates_series.datum)::timestamp with time zone, 'yyyymmdd'::text))::integer AS date_id,
    dates_series.datum AS date,
    EXTRACT(day FROM dates_series.datum) AS day_of_month,
    to_char((dates_series.datum)::timestamp with time zone, 'Dth'::text) AS day_suffix,
    to_char((dates_series.datum)::timestamp with time zone, 'Day'::text) AS day_name,
    EXTRACT(isodow FROM dates_series.datum) AS day_of_week,
    EXTRACT(doy FROM dates_series.datum) AS day_of_year,
    (to_char((dates_series.datum)::timestamp with time zone, 'W'::text))::integer AS week_of_month,
    EXTRACT(month FROM dates_series.datum) AS month_num,
    to_char((dates_series.datum)::timestamp with time zone, 'Month'::text) AS month_name,
    (date_trunc('week'::text, (dates_series.datum)::timestamp with time zone))::date AS start_of_week,
    (date_trunc('month'::text, (dates_series.datum)::timestamp with time zone))::date AS start_of_month,
    EXTRACT(year FROM dates_series.datum) AS "Year",
    (date_trunc('week'::text, (dates_series.datum)::timestamp with time zone))::date AS "Week Monday",
        CASE
            WHEN (EXTRACT(isodow FROM dates_series.datum) = ANY (ARRAY[(6)::numeric, (7)::numeric])) THEN 1
            ELSE 0
        END AS is_weekend
   FROM ( SELECT (datum.datum)::date AS datum
           FROM generate_series(('2023-01-01'::date)::timestamp with time zone, ('2050-12-31'::date)::timestamp with time zone, '1 day'::interval) datum(datum)) dates_series;


ALTER TABLE kaveri_analytics.vw_calendar OWNER TO postgres;

--
-- Name: vw_doc_reg_unassigned_applications; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_doc_reg_unassigned_applications AS
 SELECT t.financial_year,
    f.financial_year_id,
    t.monthname,
    m.month_id,
    t.srocode,
    count(DISTINCT t.applicationnumber) AS count
   FROM ((( SELECT
                CASE
                    WHEN (EXTRACT(month FROM applicantapplicationdetails.applicationstartdate) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate))::character varying)::text, 3, 2))
                    WHEN (EXTRACT(month FROM applicantapplicationdetails.applicationstartdate) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM applicantapplicationdetails.applicationstartdate), '-', (("substring"(((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate))::character varying)::text, 3, 2))::integer + 1))
                    ELSE NULL::text
                END AS financial_year,
            TRIM(TRAILING FROM to_char(applicantapplicationdetails.applicationstartdate, 'Month'::text)) AS monthname,
            applicantapplicationdetails.citizenid,
            applicantapplicationdetails.applicationnumber,
            applicantapplicationdetails.srocode,
            applicantapplicationdetails.regsrocode,
            applicantapplicationdetails.applicationtypeid,
            applicantapplicationdetails.applicationstartdate,
            applicantapplicationdetails.applicationenddate,
            applicantapplicationdetails.currentstatus,
            applicantapplicationdetails.assignedto,
            applicantapplicationdetails.aroapplicationnumber,
            applicantapplicationdetails.stamparticlecode,
            applicantapplicationdetails.stampruleid,
            applicantapplicationdetails.deedattachpath,
            applicantapplicationdetails.registrationstartdate,
            applicantapplicationdetails.registrationenddate,
            applicantapplicationdetails.lastupdatedby,
            applicantapplicationdetails.regarticlecode,
            applicantapplicationdetails.bookid,
            applicantapplicationdetails.remarks,
            applicantapplicationdetails.sfdaid,
            applicantapplicationdetails.deoid,
            applicantapplicationdetails.applicationdate,
            applicantapplicationdetails.issubmitted,
            applicantapplicationdetails.isduecorrection,
            applicantapplicationdetails.ispayment,
            applicantapplicationdetails.isdueschedule,
            applicantapplicationdetails.annexurepath,
            applicantapplicationdetails.k1k2_flag,
            applicantapplicationdetails.inserteddatetime,
            applicantapplicationdetails.refuseremarks,
            applicantapplicationdetails.remarksk
           FROM kaveri.applicantapplicationdetails
          WHERE (((applicantapplicationdetails.currentstatus)::text = 'CD101'::text) AND (applicantapplicationdetails.applicationtypeid = ANY (ARRAY[1, 2])) AND (applicantapplicationdetails.isdeleted = false) AND (applicantapplicationdetails.bookid = 1))) t
     JOIN kaveri_analytics.tbl_financial_year_master f ON ((t.financial_year = (f.financial_year)::text)))
     JOIN kaveri_analytics.tbl_month_master m ON (((m.month_name)::text = t.monthname)))
  GROUP BY t.financial_year, t.monthname, t.srocode, f.financial_year_id, m.month_id;


ALTER TABLE kaveri_analytics.vw_doc_reg_unassigned_applications OWNER TO postgres;

--
-- Name: vw_kaveri_calendar_master; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_kaveri_calendar_master AS
 SELECT t.year_num,
    t.month_name,
    t.date,
    t.day_name,
    t.week_of_month,
    t.status,
        CASE
            WHEN (t.status = 'H'::text) THEN 0
            ELSE 7
        END AS working_hrs,
        CASE
            WHEN (t.status = 'H'::text) THEN '00:00:00'::text
            ELSE '10:00:00'::text
        END AS start_time,
        CASE
            WHEN (t.status = 'H'::text) THEN '00:00:00'::text
            ELSE '17:00:00'::text
        END AS end_time
   FROM ( SELECT a.year_num,
            a.month_name,
            a.date,
            a.day_name,
            a.week_of_month,
                CASE
                    WHEN ((a.date = (b.holidaydate)::date) OR (TRIM(TRAILING FROM a.day_name) = 'Sunday'::text) OR ((a.week_of_month = ANY (ARRAY[2, 4])) AND (TRIM(TRAILING FROM a.day_name) = 'Saturday'::text))) THEN 'H'::text
                    ELSE 'W'::text
                END AS status
           FROM (kaveri_analytics.vw_calendar a
             LEFT JOIN kaveri.holidaymaster b ON ((a.date = (b.holidaydate)::date)))) t;


ALTER TABLE kaveri_analytics.vw_kaveri_calendar_master OWNER TO postgres;

--
-- Name: vw_kaveri_ec_application_delivery_status; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_kaveri_ec_application_delivery_status AS
 SELECT tbl_kaveri_ec_application_delivery_status.date,
    tbl_kaveri_ec_application_delivery_status.financial_year_id,
    tbl_kaveri_ec_application_delivery_status.financial_year,
    tbl_kaveri_ec_application_delivery_status.month_id,
    tbl_kaveri_ec_application_delivery_status.month_name,
    tbl_kaveri_ec_application_delivery_status.district_code,
        CASE
            WHEN ((("substring"(((tbl_kaveri_ec_application_delivery_status.days)::character varying)::text, 1, 1))::integer > 10) AND (tbl_kaveri_ec_application_delivery_status.flag_before_2004 = 1)) THEN '10 days and above'::text
            WHEN ((("substring"(((tbl_kaveri_ec_application_delivery_status.days)::character varying)::text, 1, 1))::integer <= 10) AND (tbl_kaveri_ec_application_delivery_status.flag_before_2004 = 1)) THEN '0-10 Days'::text
            WHEN ((("substring"(((tbl_kaveri_ec_application_delivery_status.days)::character varying)::text, 1, 1))::integer > 3) AND (tbl_kaveri_ec_application_delivery_status.flag_before_2004 = 2)) THEN '3 days and above'::text
            WHEN ((("substring"(((tbl_kaveri_ec_application_delivery_status.days)::character varying)::text, 1, 1))::integer <= 3) AND (tbl_kaveri_ec_application_delivery_status.flag_before_2004 = 2)) THEN '0-3 Days'::text
            ELSE NULL::text
        END AS status,
        CASE
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Bagalkot'::text) THEN 'Bagalkote'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Karwar'::text) THEN 'Uttar Kannada'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Chikkamagalur'::text) THEN 'Chikmagalur'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Mangalore'::text) THEN 'Dakshina Kannada'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Chikkaballapura'::text) THEN 'Chikkaballapur'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Yadagiri'::text) THEN 'Yadagir'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Davangere'::text) THEN 'Davanagere'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = 'Chamarajanagar'::text) THEN 'Chamarajanagara'::character varying
            WHEN ((tbl_kaveri_ec_application_delivery_status.district_name)::text = ANY (ARRAY[('Basavanagudi'::character varying)::text, ('Rajajinagar'::character varying)::text, ('Gandhinagar'::character varying)::text, ('Jayanagar'::character varying)::text, ('Shivajinagar'::character varying)::text])) THEN 'Bangalore Urban'::character varying
            ELSE tbl_kaveri_ec_application_delivery_status.district_name
        END AS district_name_csg,
    tbl_kaveri_ec_application_delivery_status.district_name,
    tbl_kaveri_ec_application_delivery_status.srocode,
    tbl_kaveri_ec_application_delivery_status.sroname,
    tbl_kaveri_ec_application_delivery_status.propertytype_id_csg,
    tbl_kaveri_ec_application_delivery_status.property_type,
    tbl_kaveri_ec_application_delivery_status.flag_before_2004,
    tbl_kaveri_ec_application_delivery_status.application_number,
    tbl_kaveri_ec_application_delivery_status.days
   FROM kaveri_analytics.tbl_kaveri_ec_application_delivery_status;


ALTER TABLE kaveri_analytics.vw_kaveri_ec_application_delivery_status OWNER TO postgres;

