 SELECT ta.financial_year,
    ta.monthname,
    ta.month_id,
    ta.srocode,
    ta.sroname,
    ta.district_code,
    ta.district_name,
    ta.property_type,
    COALESCE(ta.total_applications, (0)::bigint) AS total_applications,
    COALESCE(tar.total_applications_registered, (0)::bigint) AS total_applications_registered,
    COALESCE(tao.total_applications_onhold, (0)::bigint) AS total_applications_onhold,
    COALESCE(pas.total_pending_applications_sr_registration, (0)::bigint) AS total_pending_applications_sr_registration,
    COALESCE(pad.total_pending_applications_dept, (0)::bigint) AS total_pending_applications_dept,
    COALESCE(awc.total_applications_citizen_withdrawal, (0)::bigint) AS total_applications_citizen_withdrawal,
    COALESCE(ars.total_applications_refused_sro, (0)::bigint) AS total_applications_refused_sro,
    COALESCE(aos.total_applications_other_status, (0)::bigint) AS total_applications_other_status,
    COALESCE(rev.stamp_duty, ((0)::numeric)::double precision) AS stamp_duty,
    COALESCE(rev.registration_fee, ((0)::numeric)::double precision) AS registration_fee,
    COALESCE(rev.total_revenue, ((0)::numeric)::double precision) AS total_revenue
   FROM ((((((((total_applications ta
     LEFT JOIN total_applications_registered tar ON (((ta.financial_year = tar.financial_year) AND (ta.month_id = tar.month_id) AND (ta.srocode = tar.srocode) AND (ta.district_code = tar.district_code) AND (ta.property_type = tar.property_type))))
     LEFT JOIN total_applications_onhold tao ON (((ta.financial_year = tao.financial_year) AND (ta.month_id = tao.month_id) AND (ta.srocode = tao.srocode) AND (ta.district_code = tao.district_code) AND (ta.property_type = tao.property_type))))
     LEFT JOIN pending_applications_sr_registration pas ON (((ta.financial_year = pas.financial_year) AND (ta.month_id = pas.month_id) AND (ta.srocode = pas.srocode) AND (ta.district_code = pas.district_code) AND (ta.property_type = pas.property_type))))
     LEFT JOIN pending_applications_dept pad ON (((ta.financial_year = pad.financial_year) AND (ta.month_id = pad.month_id) AND (ta.srocode = pad.srocode) AND (ta.district_code = pad.district_code) AND (ta.property_type = pad.property_type))))
     LEFT JOIN applications_withdrawal_citizen awc ON (((ta.financial_year = awc.financial_year) AND (ta.month_id = awc.month_id) AND (ta.srocode = awc.srocode) AND (ta.district_code = awc.district_code) AND (ta.property_type = awc.property_type))))
     LEFT JOIN applications_refused_sro ars ON (((ta.financial_year = ars.financial_year) AND (ta.month_id = ars.month_id) AND (ta.srocode = ars.srocode) AND (ta.district_code = ars.district_code) AND (ta.property_type = ars.property_type))))
     LEFT JOIN applications_other_status aos ON (((ta.financial_year = aos.financial_year) AND (ta.month_id = aos.month_id) AND (ta.srocode = aos.srocode) AND (ta.district_code = aos.district_code) AND (ta.property_type = aos.property_type))))
     LEFT JOIN kaveri_analytics.vw_applications_total_revenue_summary rev ON (((ta.financial_year = rev.financial_year) AND (ta.monthname = rev.monthname) AND (ta.srocode = rev.srocode) AND (ta.district_code = rev.district_code) AND (ta.property_type = rev.property_type))));


