            WHEN (((x.difference)::double precision >= (4)::double precision) AND ((x.difference)::double precision <= (5)::double precision)) THEN '4-5 Days'::text
            WHEN (((x.difference)::double precision >= (6)::double precision) AND ((x.difference)::double precision <= (10)::double precision)) THEN '6-10 Days'::text
