            (now())::date AS "current_date",
            kaveri_analytics.fn_total_working_days((max(e.crtdt))::date, CURRENT_DATE) AS difference
           FROM (( SELECT DISTINCT a.applicationnumber,
                    a.srocode,
                        CASE
                            WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
                            ELSE NULL::text
                        END AS property_type,
                    a.currentstatus,
                    max(d.crtdt) AS status_change_date
                   FROM (((kaveri.applicantapplicationdetails a
                     JOIN kaveri.propertymaster b ON (((a.applicationnumber)::text = (b.applicationnumber)::text)))
                     JOIN kaveri.documentmaster c ON (((a.applicationnumber)::text = (c.applicationnumber)::text)))
                     JOIN kaveri.applicationaudit d ON ((((a.applicationnumber)::text = (d.applicationnumber)::text) AND ((d.wrkflowstatusid)::text = (a.currentstatus)::text))))
                  WHERE (((a.currentstatus)::text = ANY (ARRAY[('CD108'::character varying)::text, ('CD109'::character varying)::text, ('CD110'::character varying)::text, ('CD111'::character varying)::text, ('CD112'::character varying)::text, ('CD113'::character varying)::text, ('CD114'::character varying)::text, ('CD115'::character varying)::text, ('CD116'::character varying)::text, ('CD117'::character varying)::text])) AND (a.applicationtypeid = ANY (ARRAY[1, 2])) AND (a.bookid = 1) AND (b.propertytypeid <> 1001) AND (b.propertytypeid = ANY (ARRAY[17, 18])))
                  GROUP BY a.applicationnumber, a.srocode,
                        CASE
                            WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
                            ELSE NULL::text
                        END, a.currentstatus) t
             JOIN kaveri.applicationaudit e ON ((((t.applicationnumber)::text = (e.applicationnumber)::text) AND ((e.wrkflowstatusid)::text = 'CD108'::text))))
          GROUP BY t.applicationnumber,
                CASE
                    WHEN (EXTRACT(month FROM t.status_change_date) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM t.status_change_date) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM t.status_change_date))::character varying)::text, 3, 2))
                    WHEN (EXTRACT(month FROM t.status_change_date) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM t.status_change_date), '-', (("substring"(((EXTRACT(year FROM t.status_change_date))::character varying)::text, 3, 2))::integer + 1))
                    ELSE NULL::text
                END, (TRIM(TRAILING FROM to_char(t.status_change_date, 'Month'::text))), t.srocode, t.property_type, t.currentstatus, t.status_change_date) x,
    kaveri_analytics.tbl_district_sro_mapping m
  WHERE (x.srocode = m.srocode)
  GROUP BY x.financial_year, x.monthname, x.srocode, x.property_type,
        CASE
