--
-- Name: vw_total_applications_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_total_applications_agriculture AS
 SELECT 2 AS kaveri_v1_v2,
        CASE
            WHEN ((t.currentstatus)::text = 'CD120'::text) THEN
            CASE
                WHEN (EXTRACT(month FROM t.ackdatetime) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM t.ackdatetime) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM t.ackdatetime))::character varying)::text, 3, 2))
                WHEN (EXTRACT(month FROM t.ackdatetime) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM t.ackdatetime), '-', (("substring"(((EXTRACT(year FROM t.ackdatetime))::character varying)::text, 3, 2))::integer + 1))
                ELSE NULL::text
            END
            ELSE
            CASE
                WHEN (EXTRACT(month FROM t.crtdt) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM t.crtdt) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM t.crtdt))::character varying)::text, 3, 2))
                WHEN (EXTRACT(month FROM t.crtdt) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM t.crtdt), '-', (("substring"(((EXTRACT(year FROM t.crtdt))::character varying)::text, 3, 2))::integer + 1))
                ELSE NULL::text
            END
        END AS financial_year,
        CASE
            WHEN ((t.currentstatus)::text = 'CD120'::text) THEN TRIM(TRAILING FROM to_char(t.ackdatetime, 'Month'::text))
            ELSE TRIM(TRAILING FROM to_char(t.crtdt, 'Month'::text))
        END AS monthname,
    t.srocode,
