          WHERE (((a.currentstatus)::text = 'CD119'::text) AND (a.applicationtypeid = ANY (ARRAY[1, 2])) AND (a.bookid = 1) AND (b.propertytypeid <> 1001) AND (b.propertytypeid = ANY (ARRAY[17, 18])))
          GROUP BY a.applicationnumber,
                CASE
                    WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
