--
-- Name: vw_total_applications_refused_sro_agriculture; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_total_applications_refused_sro_agriculture AS
 SELECT DISTINCT t.applicationnumber,
        CASE
            WHEN (EXTRACT(month FROM t.crtdt) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM t.crtdt) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM t.crtdt))::character varying)::text, 3, 2))
            WHEN (EXTRACT(month FROM t.crtdt) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM t.crtdt), '-', (("substring"(((EXTRACT(year FROM t.crtdt))::character varying)::text, 3, 2))::integer + 1))
            ELSE NULL::text
        END AS financial_year,
    TRIM(TRAILING FROM to_char(t.crtdt, 'Month'::text)) AS monthname,
    t.srocode,
    t.sroname,
    t.district_code,
    t.district_name,
    t.property_type,
    t.remarks,
    t.crtdt,
    t.remarks_short
   FROM ( SELECT DISTINCT a.applicationnumber,
            a.srocode,
            m.sroname,
            m.district_code_agri AS district_code,
            m.district_name_agri AS district_name,
            b.propertytypeid,
                CASE
                    WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
                    ELSE NULL::text
                END AS property_type,
            a.remarks,
            max(e.crtdt) AS crtdt,
                CASE
                    WHEN (a.remarks = 'The document is refused to register as per sec 19 read with rule 171 (i) of the Registration act 1908 and Karnataka Registration Rules 1965. '::text) THEN 'sec 19 with rule 171(i)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 20 read with rule 171 (ii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 20 with rule 171(ii)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 21(1) to (3) and sec 22 read with rule 171 (iii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 21(1)to(3) and sec 22 with rule 171(iii)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 21(4) read with rule 171 (iv) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 21(4) with rule 171(iv)'::text
                    WHEN (a.remarks = 'The document is refused to register as per rule 50 read with rule 171 (v) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'rule 50 read with rule 171(v)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 23, 24, 25, 26, 72, 75 and 77 read with rule 171 (vi) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 23,24,25,26,72,75 and 77 with rule 171(vi)'::text
                    WHEN (a.remarks = 'The document is refused to register as per  sec 32, 33, 40 and 43 read with rule 171 (vii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 32,33,40 and 43 with rule 171(vii)'::text
                    WHEN (a.remarks = ' The document is refused to registered as per  sec 34read with rule 171 (viii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 34 read with rule 171(viii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per  sec 32 and 43 read with rule 171 (ix) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 32 and 43 read with rule 171(ix)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 34 and 40 read with rule 171 (x) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 34 and 40 read with rule 171(x)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 read with rule 171 (xi) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xi)'::text
                    WHEN (a.remarks = ' The document is refused to ster as per sec 35 read with rule 171 (xii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 read with rule 171 (xiii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xiii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 and 41 read with rule 171 (xiii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 and 41 read with rule 171(xiii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 41 read with rule 171 (xv) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 41 read with rule 171(xv)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 25, 34, 80 read with rule 171 (xvi) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 25,34,80 read with rule 171(xvi)'::text
                    ELSE NULL::text
                END AS remarks_short
           FROM (((((kaveri.applicantapplicationdetails a
             JOIN kaveri.propertymaster b ON (((a.applicationnumber)::text = (b.applicationnumber)::text)))
             JOIN kaveri.documentmaster c ON (((b.applicationnumber)::text = (c.applicationnumber)::text)))
             JOIN kaveri.reasonmaster r ON ((a.remarks = (r.reasontype)::text)))
             JOIN kaveri_analytics.tbl_district_sro_mapping m ON ((a.srocode = m.srocode)))
             JOIN kaveri.applicationaudit e ON ((((a.applicationnumber)::text = (e.applicationnumber)::text) AND ((a.currentstatus)::text = (e.wrkflowstatusid)::text))))
          WHERE ((a.applicationtypeid = ANY (ARRAY[1, 2])) AND ((a.currentstatus)::text = 'CD134'::text) AND (a.bookid = 2) AND (b.propertytypeid <> 1001) AND (b.propertytypeid = ANY (ARRAY[17, 18])))
          GROUP BY a.applicationnumber, a.srocode, m.sroname, m.district_code_agri, m.district_name_agri, b.propertytypeid,
                CASE
                    WHEN (b.propertytypeid = ANY (ARRAY[17, 18])) THEN 'Agriculture'::text
                    ELSE NULL::text
                END, a.remarks,
                CASE
                    WHEN (a.remarks = 'The document is refused to register as per sec 19 read with rule 171 (i) of the Registration act 1908 and Karnataka Registration Rules 1965. '::text) THEN 'sec 19 with rule 171(i)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 20 read with rule 171 (ii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 20 with rule 171(ii)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 21(1) to (3) and sec 22 read with rule 171 (iii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 21(1)to(3) and sec 22 with rule 171(iii)'::text
                    WHEN (a.remarks = 'The document is refused to register as per sec 21(4) read with rule 171 (iv) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 21(4) with rule 171(iv)'::text
                    WHEN (a.remarks = 'The document is refused to register as per rule 50 read with rule 171 (v) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'rule 50 read with rule 171(v)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 23, 24, 25, 26, 72, 75 and 77 read with rule 171 (vi) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 23,24,25,26,72,75 and 77 with rule 171(vi)'::text
                    WHEN (a.remarks = 'The document is refused to register as per  sec 32, 33, 40 and 43 read with rule 171 (vii) the Registration act 1908 and Karnataka Registration Rules 1965.'::text) THEN 'sec 32,33,40 and 43 with rule 171(vii)'::text
                    WHEN (a.remarks = ' The document is refused to registered as per  sec 34read with rule 171 (viii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 34 read with rule 171(viii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per  sec 32 and 43 read with rule 171 (ix) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 32 and 43 read with rule 171(ix)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 34 and 40 read with rule 171 (x) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 34 and 40 read with rule 171(x)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 read with rule 171 (xi) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xi)'::text
                    WHEN (a.remarks = ' The document is refused to ster as per sec 35 read with rule 171 (xii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 read with rule 171 (xiii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 read with rule 171(xiii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 35 and 41 read with rule 171 (xiii) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 35 and 41 read with rule 171(xiii)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 41 read with rule 171 (xv) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 41 read with rule 171(xv)'::text
                    WHEN (a.remarks = ' The document is refused to register as per sec 25, 34, 80 read with rule 171 (xvi) the Registration act 1908 and Karnataka Registration Rules 1965.  '::text) THEN 'sec 25,34,80 read with rule 171(xvi)'::text
                    ELSE NULL::text
                END) t;


