    vw_total_count_regarticlewise_non_agriculture.district_name,
    vw_total_count_regarticlewise_non_agriculture.property_type,
    vw_total_count_regarticlewise_non_agriculture.regarticlecode,
    vw_total_count_regarticlewise_non_agriculture.articlenamee,
    vw_total_count_regarticlewise_non_agriculture.total_count
   FROM kaveri_analytics.vw_total_count_regarticlewise_non_agriculture;


ALTER TABLE kaveri_analytics.vw_total_count_regarticlewise_summary OWNER TO postgres;

--
-- Name: vw_unassigned_applications; Type: VIEW; Schema: kaveri_analytics; Owner: postgres
--

CREATE VIEW kaveri_analytics.vw_unassigned_applications AS
 SELECT t.financial_year,
    t.monthname,
    t.srocode,
    count(DISTINCT t.applicationnumber) AS count
   FROM ( SELECT
                CASE
                    WHEN (EXTRACT(month FROM applicantapplicationdetails.applicationstartdate) = ANY (ARRAY[(1)::numeric, (2)::numeric, (3)::numeric])) THEN concat((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate) - (1)::numeric), '-', "substring"(((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate))::character varying)::text, 3, 2))
                    WHEN (EXTRACT(month FROM applicantapplicationdetails.applicationstartdate) = ANY (ARRAY[(4)::numeric, (5)::numeric, (6)::numeric, (7)::numeric, (8)::numeric, (9)::numeric, (10)::numeric, (11)::numeric, (12)::numeric])) THEN concat(EXTRACT(year FROM applicantapplicationdetails.applicationstartdate), '-', (("substring"(((EXTRACT(year FROM applicantapplicationdetails.applicationstartdate))::character varying)::text, 3, 2))::integer + 1))
                    ELSE NULL::text
                END AS financial_year,
            TRIM(TRAILING FROM to_char(applicantapplicationdetails.applicationstartdate, 'Month'::text)) AS monthname,
            applicantapplicationdetails.citizenid,
            applicantapplicationdetails.applicationnumber,
            applicantapplicationdetails.srocode,
            applicantapplicationdetails.regsrocode,
            applicantapplicationdetails.applicationtypeid,
            applicantapplicationdetails.applicationstartdate,
            applicantapplicationdetails.applicationenddate,
            applicantapplicationdetails.currentstatus,
            applicantapplicationdetails.assignedto,
            applicantapplicationdetails.aroapplicationnumber,
            applicantapplicationdetails.stamparticlecode,
            applicantapplicationdetails.stampruleid,
            applicantapplicationdetails.deedattachpath,
            applicantapplicationdetails.registrationstartdate,
            applicantapplicationdetails.registrationenddate,
            applicantapplicationdetails.lastupdatedby,
            applicantapplicationdetails.regarticlecode,
            applicantapplicationdetails.bookid,
            applicantapplicationdetails.remarks,
            applicantapplicationdetails.sfdaid,
            applicantapplicationdetails.deoid,
            applicantapplicationdetails.applicationdate,
            applicantapplicationdetails.issubmitted,
            applicantapplicationdetails.isduecorrection,
            applicantapplicationdetails.ispayment,
            applicantapplicationdetails.isdueschedule,
            applicantapplicationdetails.annexurepath,
            applicantapplicationdetails.k1k2_flag,
            applicantapplicationdetails.inserteddatetime,
            applicantapplicationdetails.refuseremarks,
            applicantapplicationdetails.remarksk
           FROM kaveri.applicantapplicationdetails
          WHERE (((applicantapplicationdetails.currentstatus)::text = 'CD101'::text) AND (applicantapplicationdetails.applicationtypeid = ANY (ARRAY[1, 2])) AND (applicantapplicationdetails.isdeleted = false) AND (applicantapplicationdetails.bookid = 1))) t
  GROUP BY t.financial_year, t.monthname, t.srocode;


ALTER TABLE kaveri_analytics.vw_unassigned_applications OWNER TO postgres;

